window.TCS_MODULES=[{"id": "M1", "en": "Community as a Client", "ar": "المجتمع بوصفه عميلاً", "scenarios": ["S1"], "slides": [{"n": 1, "title": "Community as a client: applying the nursing process", "blocks": [{"k": "list", "items": [[0, "NUR 415 – 2025/26"]]}], "notes": "", "pics": 1}, {"n": 2, "title": "Objectives", "blocks": [{"k": "list", "items": [[0, "Describe the characteristics of a healthy community."], [0, "Describe the meaning of community as client."], [0, "Articulate three specific considerations of each of the three dimensions of the community as client."], [0, "Explain methods the community health nurse might use to interact with the community."], [0, "Discuss methods of community health assessment."], [0, "Compare and contrast five types of community assessment."], [0, "Delineate five sources of community data."], [0, "Describe the role of the community health nurse as a catalyst for community development."]]}], "notes": "", "pics": 0}, {"n": 3, "title": "Community as a client", "blocks": [{"k": "list", "items": [[0, "The concept of community as client refers to a group or population of people as the focus of nursing service (Anderson & McFarlane, 2015)"], [0, "It is a new experience to think of an entire community as your focus of care, but similar principles apply"]]}], "notes": "", "pics": 0}, {"n": 4, "title": "WHAT IS A HEALTHY COMMUNITY", "blocks": [{"k": "list", "items": [[0, "A community’s health can be viewed within the context of health being more than just the absence of disease and including things that promote the maintenance of a high quality of life and productivity"]]}], "notes": "", "pics": 0}, {"n": 5, "title": "Dimensions of Community as a Client", "blocks": [], "notes": "", "pics": 0}, {"n": 6, "title": "Status/people", "blocks": [{"k": "list", "items": [[0, "The most common measure of health of the community."], [0, "It comprises of morbidity and mortality data identifying the physical, emotional and social determinants of health."], [1, "The physical and social indices include- vital statistics, leading causes of death and illness, suicide rates, rates of drug and alcohol addiction."], [1, "Social determinants  are- crime rates, functional ability level, or high-school drop out rates, average income levels, single, female-leaded households."]]}], "notes": "", "pics": 0}, {"n": 7, "title": "Structure", "blocks": [{"k": "list", "items": [[0, "Refers to its services and resources, which can include:"], [0, "E.g.1 adequacy and appropriateness of health services, and utilization of it,  number and type of health and social services, and quality measures."], [0, "E.g.2 Also availability of health care providers- nurses, doctors, dentists etc."], [0, "E.g.3. Demographic data such as socio-economic and racial distribution, age, gender and educational level."]]}], "notes": "", "pics": 0}, {"n": 8, "title": "The Processes", "blocks": [{"k": "list", "items": [[0, "refers to its ability of the community to function effectively."], [0, "This can see through the collaboration between community with other subsystems such as education and health (e.g. With municipality, educational institutions, environment, media etc)."]]}], "notes": "", "pics": 0}, {"n": 9, "title": "Three features of Community", "blocks": [{"k": "list", "items": [[0, "Another perspective identifies community as having three features which are analyzed while assessing the health of the community as follow:"], [0, "Location"], [0, "Population."], [0, "Social system."]]}], "notes": "", "pics": 1}, {"n": 10, "title": "Three features of Community", "blocks": [{"k": "list", "items": [[0, "1- Location"]]}], "notes": "", "pics": 1}, {"n": 11, "title": "Location features", "blocks": [{"k": "list", "items": [[0, "Health of the community is affected by location."], [0, "It can be offering resources or threats."], [0, "A healthy community is one that makes wise use of resources and is prepared to meet the threats and dangers."], [0, "E.g. Zinj area has lots of services, restaurants, gym or sports centers, walkable/ garden areas."]]}], "notes": "", "pics": 1}, {"n": 12, "title": "The Six Location Variables", "blocks": [], "notes": "", "pics": 0}, {"n": 13, "title": "", "blocks": [], "notes": "", "pics": 1}, {"n": 14, "title": "", "blocks": [], "notes": "", "pics": 1}, {"n": 15, "title": "Match the Variable", "blocks": [], "notes": "Geographic features\nLocation of health service\nClimate\nFlora and fauna\nHuman made environment", "pics": 0}, {"n": 16, "title": "Three features of Community", "blocks": [{"k": "list", "items": [[0, "2- Population"]]}], "notes": "", "pics": 1}, {"n": 17, "title": "Population Characteristics", "blocks": [{"k": "list", "items": [[0, "The population consists not of a specialized aggregate but of all the diverse people who live within the boundaries of the community."], [0, "The health of any community is greatly influenced by the attributes of its population"], [0, "The various variables in the population are:"], [1, "Size"], [1, "Density"], [1, "Composition or demography"], [1, "Rate of growth or decline"], [1, "Cultural characteristics"], [1, "Social class structure"], [1, "Mobility"]]}], "notes": "", "pics": 1}, {"n": 18, "title": "Population  Size", "blocks": [{"k": "list", "items": [[0, "The population size can affect the health of the community."], [0, "E.g. Large number of geriatric population may need resources for the care."], [0, "Large crowd of population also create environmental sanitation problems."], [0, "Heterogeneity is another factor which affect the health."], [0, "E.g. A community with large number of males/ children etc, we may need to plan services accordingly."]]}], "notes": "", "pics": 1}, {"n": 19, "title": "Population  Density", "blocks": [{"k": "list", "items": [[0, "The population density can affect the health of the community."], [0, "E.g. overcrowded or congested housing."], [0, "Creates also environmental hazards – like smoke pollution (due to vehicles smoke), more number of motor vehicle accidents, lung problems etc."], [0, "On the opposite, What is the disadvantage of low-density community?"]]}], "notes": "", "pics": 1}, {"n": 20, "title": "Composition/ Demographics", "blocks": [{"k": "list", "items": [[0, "The composition of the population density can be a concern or an interest."], [0, "E.g. Communities with a high proportion of high-income families/ low-income families."], [0, "E.g. Communities with a large number of children."], [0, "Communities with a large number of smokers."]]}], "notes": "", "pics": 1}, {"n": 21, "title": "Rate of Growth or Decline", "blocks": [{"k": "list", "items": [[0, "The populations change over time due to economic growth or due to better living conditions."], [0, "E.g. A shift of population occur in some areas as some of them move towards other residential areas."]]}], "notes": "", "pics": 1}, {"n": 22, "title": "Cultural Characteristics", "blocks": [{"k": "list", "items": [[0, "A community can have one or many cultures."], [0, "E.g. Manama area can have different cultures due to expatriate populations."]]}], "notes": "", "pics": 1}, {"n": 23, "title": "Social class and Educational level", "blocks": [{"k": "list", "items": [[0, "Social class refers to the ranking of groups within society by income, education, occupation, prestige, or a combination of these factors."], [0, "Class rankings are usually based on occupation, education and wealth (income or assets)."], [0, "These comprises the social and physical determinants of health."], [0, "E.g. upper, middle, lower etc."]]}], "notes": "", "pics": 1}, {"n": 24, "title": "Mobility", "blocks": [{"k": "list", "items": [[0, "Population turnover may affect the health of the population."], [0, "Continuity of services can be affected."], [0, "Nomadic populations sometimes present with special health needs."], [0, "E.g. Traveling community causes defaulter children, and not completing vaccinations."], [0, "E.g. Visiting certain countries causes contracting diseases like yellow fever."]]}], "notes": "", "pics": 1}, {"n": 25, "title": "Three features of Community", "blocks": [{"k": "list", "items": [[0, "3- Social System"]]}, {"k": "list", "items": [[0, "Every community has a social system."], [0, "The various parts of a community’s social system that interact and influence the health of the community are called social system variables"]]}], "notes": "", "pics": 1}, {"n": 26, "title": "Social System", "blocks": [{"k": "list", "items": [[0, "For example, a high rate of Sickle cell marriage in a city may signal inadequate functioning of several systems (e.g., family, educational, religious, health), so a closer look is in order."], [0, "What community values influence marital decisions and behavior among adolescents? What pre-marital education programs are available to this population? Does the health system provide information and counseling?"]]}], "notes": "", "pics": 0}, {"n": 27, "title": "Nursing Process", "blocks": [{"k": "list", "items": [[0, "Applied to the  Community as A Client"]]}], "notes": "", "pics": 1}, {"n": 28, "title": "Community needs assessment", "blocks": [{"k": "list", "items": [[0, "Community health assessment is the process of determining the real or perceived needs of a defined community"], [1, "Windshield survey (familiarization assessment)"], [1, "Problem-oriented assessment"], [1, "Community subsystem assessment"], [1, "Comprehensive assessment (key informants)"], [1, "Community assets assessment"]]}], "notes": "", "pics": 0}, {"n": 29, "title": "Familiarization assessment", "blocks": [{"k": "list", "items": [[0, "Familiarization assessment involves studying data already available on a community and  then gathering a certain amount of firsthand data in order to gain a working knowledge of the community"]]}], "notes": "", "pics": 0}, {"n": 30, "title": "problem-oriented assessment", "blocks": [{"k": "list", "items": [[0, "problem-oriented assessment, begins with a single problem and assesses the community in terms of that problem"], [0, "e.g. first step would be to discover the incidence of childhood deafness, both in the community and in the state. Second, she might begin interviewing officials in the schools and health institutions to find out what had been done in the past to assist deaf children. She could do an Internet search to locate available resources on the subject of deafness. Are there interpreters available for people who use sign language? How do hospitals and courts approach deafness? Are there any clubs or other organizations for deaf people? Are there school programs for the deaf, and if so, where are they located?"]]}], "notes": "", "pics": 0}, {"n": 31, "title": "community subsystem assessment", "blocks": [{"k": "list", "items": [[0, "In community subsystem assessment, the community health nurse focuses on a single dimension of community life."], [0, "For example, the nurse might decide to survey churches and religious organizations to discover their roles in the community."]]}], "notes": "", "pics": 0}, {"n": 32, "title": "Comprehensive Community assessment", "blocks": [{"k": "list", "items": [[0, "Comprehensive assessment seeks to discover all relevant community health information."], [0, "Key informants are interviewed in every major system— education, health, religious, economic, and others."]]}], "notes": "", "pics": 0}, {"n": 33, "title": "Community Assets Assessment", "blocks": [{"k": "list", "items": [[0, "This method of assessment focuses on the strengths and capacities of a community rather than its problems."], [0, "The capacities and skills of community members are identified, with a focus on creating or rebuilding relationships among local residents, associations, and institutions to multiply power and effectiveness."], [0, "This approach requires that the assessor look for the positive or see the glass as half full."]]}], "notes": "", "pics": 1}, {"n": 34, "title": "What type of assessment is being used here?", "blocks": [{"k": "list", "items": [[0, "Scenario: A health department is investigating a sudden increase in asthma cases in a specific area. They survey residents to identify potential triggers such as air quality issues or exposure to allergens."], [0, "Scenario: Community health workers conduct in-depth interviews with local leaders, healthcare providers, and residents to gather information about health concerns, resources, and barriers to care in the community."]]}], "notes": "Problem-Oriented Assessment\nComprehensive Assessment", "pics": 0}, {"n": 35, "title": "What type of assessment is being used here?", "blocks": [{"k": "list", "items": [[0, "Scenario: A group of nursing students drives through a neighborhood to observe the condition of parks, schools, and grocery stores, noting the overall cleanliness and safety of the environment."], [0, "Scenario: A local organization is analyzing the health education services available in the community, focusing on schools, clinics, and community centers to assess their effectiveness in promoting healthy lifestyles."]]}], "notes": "Windshield Survey\nCommunity Subsystem Assessment", "pics": 0}, {"n": 36, "title": "What type of assessment is being used here?", "blocks": [{"k": "list", "items": [[0, "Scenario: A community group maps out local resources such as parks, fitness centers, food banks, and support groups to understand existing strengths that can be leveraged for health promotion initiatives."], [0, "Scenario: A health advocacy group organizes a workshop to inventory community resources like vaccination clinics, health fairs, and exercise classes, aiming to enhance access to preventive healthcare services for low-income families."]]}], "notes": "Community Assets Assessment", "pics": 0}, {"n": 37, "title": "Community Assessment Methods", "blocks": [{"k": "list", "items": [[0, "Surveys"], [0, "Descriptive epidemiologic studies"], [0, "Community forums/town hall meetings"], [0, "Focus groups"]]}], "notes": "", "pics": 1}, {"n": 38, "title": "Community Nursing Diagnosis", "blocks": [{"k": "list", "items": [[0, "presents a community focus"], [0, "Include statements narrow enough to guide interventions"], [0, "Use a community response instead of a risk, goal, or need statement"], [0, "Include factors within the domain of community health nursing intervention"]]}], "notes": "", "pics": 0}, {"n": 39, "title": "Wellness nursing diagnosis", "blocks": [{"k": "list", "items": [[0, "Wellness nursing diagnosis for an assisted living community of elders."], [0, "The senior residents of an assisted living center (community focus) have the potential for achieving optimal functioning related to (host factors) their expressed interest in exercise, diet, and meaningful activities and to (environmental factors) their access to exercise opportunities, nutritional information, and social outlets."]]}], "notes": "", "pics": 0}, {"n": 40, "title": "Deficit community nursing diagnosis", "blocks": [{"k": "list", "items": [[0, "Deficit community nursing diagnosis for a rural farmworker community."], [0, "The inhabitants of (name of the town) in (name of the state) are at risk for illness and injury related to (host factors) exposure to pesticides, lack of motivation to add or use safety devices on farm machinery, lack of safety knowledge, choice to take unnecessary risks (environmental factors), lack of family income to purchase newer equipment, and long hours of work that lead to stress and exhaustion."]]}], "notes": "", "pics": 0}, {"n": 41, "title": "PLANNING to Meet Community Health Needs", "blocks": [{"k": "list", "items": [[0, "Planning is the logical decision-making process used to design an orderly detailed serious of actions for accomplishing specific goals and objectives"], [0, "List needs in order to priority"], [0, "Establish goals and objectives"], [0, "Write an action plan"]]}], "notes": "", "pics": 1}, {"n": 42, "title": "Implementation", "blocks": [{"k": "list", "items": [[0, "Implementation is putting the plan into action. The nurse, other professionals, or clients  carry out the activities of the plan"], [0, "Implementation starts with Preparation"], [0, "“Who, what, when, where and how”"], [0, "“Who will be involved in carrying out the plan”"], [0, "“What are each person ‘ responsibilities”"], [0, "“Do all understand why and how to do their parts"]]}], "notes": "", "pics": 1}, {"n": 43, "title": "Implementation", "blocks": [{"k": "list", "items": [[0, "The process of implementation requires a series of nursing actions or activities"], [0, "Applies system or change theory"], [0, "Facilitate an environment conductive to carrying out the plan"], [0, "Prepare clients to receive services"], [0, "Carry out the plan, modify and then carried out by professionals and clients"], [0, "Monitor and document process"]]}], "notes": "", "pics": 1}, {"n": 44, "title": "Evaluation", "blocks": [{"k": "list", "items": [[0, "Measuring or judging effectiveness of goal or outcome attainment"], [0, "Formative: focus on process during actual interventions"], [0, "Summative: focus on the outcomes of interventions; effect; impact"]]}], "notes": "", "pics": 1}, {"n": 45, "title": "Thank you", "blocks": [], "notes": "", "pics": 0}]}, {"id": "M2", "en": "Family as a Client", "ar": "الأسرة بوصفها عميلاً", "scenarios": ["S2"], "slides": [{"n": 1, "title": "Family as A Client: Applying the Nursing Process", "blocks": [{"k": "list", "items": [[0, "NUR415, October 2025"]]}], "notes": "", "pics": 2}, {"n": 2, "title": "Learning Objectives", "blocks": [{"k": "list", "items": [[0, "At the end of this session, students will be able to:"], [0, "Define family health nursing."], [0, "Analyze definitions of family."], [0, "Discuss characteristics all families have in common."], [0, "Identify types od family."], [0, "Discuss skills used during home visits."], [0, "Describe components of the family home visits."], [0, "List specific safety measures the community/public health nurse should take when traveling to a home or making a home visit."], [0, "Describe the data collection categories for family health assessment."], [0, "List the five basic principles the community/public health nurse should follow when assessing family health."], [0, "Describe the three types of evaluations that are necessary after family health interventions."]]}], "notes": "", "pics": 1}, {"n": 3, "title": "Introduction", "blocks": [{"k": "list", "items": [[0, "The family plays a critical role in the health of its members."], [0, "Health habits such as preventative care, diet, exercise, and physical activity are developed in the context of family."], [0, "Health beliefs, genetic influences, and care of the ill family member all take place within the family environment."], [0, "The community health nurse is in a unique position to influence and promote family health."]]}], "notes": "", "pics": 1}, {"n": 4, "title": "Definitions", "blocks": [{"k": "list", "items": [[0, "Family"]]}, {"k": "list", "items": [[0, "“The basic unit of society”"], [0, "“two or more individuals who depend on one another for emotional, physical, and economical support."], [0, "“Family is who they say they are”"]]}], "notes": "", "pics": 1}, {"n": 5, "title": "Definitions", "blocks": [{"k": "list", "items": [[0, "Family Health:"], [0, "“Dynamic changing state of wellbeing, which includes the biological, psychological, spiritual, sociological, and culture factors of individual members and the whole family system”"]]}], "notes": "", "pics": 1}, {"n": 6, "title": "Definitions", "blocks": [{"k": "list", "items": [[0, "Family Health Nursing:"], [0, "\"The practical science of preventative and remedial support to the family in order to help the family system unit independently and maintain & improve its family functions.”"]]}], "notes": "", "pics": 1}, {"n": 7, "title": "Universal Characteristics of Families", "blocks": [{"k": "list", "items": [[0, "1. Every family is a small social system."], [0, "Families are interdependent."], [0, "Families maintain boundaries."], [0, "Families exchange energy with their environments."], [0, "Families adapt."], [0, "Families are goal oriented (providing love, security, and a sense of belonging)."], [0, "2. Every family moves through stages in its life cycle."], [0, "3. Every family has its own cultural values and rules."], [0, "4. Family members share certain values that affect their behavior."]]}], "notes": "", "pics": 1}, {"n": 8, "title": "Universal Characteristics of Families", "blocks": [{"k": "list", "items": [[0, "5. Certain roles are defined for family members."], [0, "6. A family's culture influences its distribution and use of power."], [0, "7. Every family has structure."], [0, "8. Every family has certain basic functions:"], [0, "Providing affection"], [0, "Providing security"], [0, "Instilling identity"], [0, "Promoting affiliation"], [0, "Providing socialization"], [0, "Establishing controls"]]}], "notes": "", "pics": 1}, {"n": 9, "title": "Family Stage of Development", "blocks": [], "notes": "", "pics": 1}, {"n": 10, "title": "Types of Families", "blocks": [], "notes": "", "pics": 0}, {"n": 11, "title": "Types of Families “Traditional Families” reflect structures that were historically considered the “norm” in many societies and reinforced by religion, education, and cultural institutions.", "blocks": [], "notes": "", "pics": 0}, {"n": 12, "title": "Types of Families “Contemporary Families” reflect social, cultural, and economic shifts that challenge the traditional “ideal.” These forms are increasingly accepted and visible in media, communities, and healthcare.", "blocks": [], "notes": "", "pics": 0}, {"n": 13, "title": "Types of Families “Contemporary Families”", "blocks": [], "notes": "", "pics": 0}, {"n": 14, "title": "Q?? Types of Families", "blocks": [{"k": "list", "items": [[0, "A household consists of J, his wife M, and their two biological children, D and S. They all live together in one family home. J works as an engineer, while M is a teacher."], [0, "After her divorce, A lives alone with her young son, K. She is solely responsible for the family's income, caregiving, and household decisions."], [0, "M and her daughter E moved in with C and his son J after they got married. Now, all four of them live together, navigating new relationships and merging their family traditions."]]}], "notes": "", "pics": 0}, {"n": 15, "title": "Q?? Types of Families", "blocks": [{"k": "list", "items": [[0, "M and L have been together for five years and share an apartment. They have a dog and are both focused on their careers. They are not married but consider each other life partners."], [0, "Seventeen-year-old C lives with her mother and her newborn baby, L. She is balancing her responsibilities as a new mother while trying to finish high school with the support of her family."], [0, "D and S have been certified by the state to provide a temporary, safe, and loving home. They are currently caring for 8-year-old Leo, who was placed with them while his biological parents receive counseling and support to overcome challenges."]]}], "notes": "", "pics": 0}, {"n": 16, "title": "Working with Family: Home Visit", "blocks": [{"k": "list", "items": [[0, "The family is the client and unit of service."], [0, "The Home as a Unique Setting:"], [1, "The nurse is a guest in the family's most intimate space."], [1, "Entry is based on mutual trust: the family trusts the nurse to help, and the nurse trusts the family's welcome."], [0, "Nurse's Preparation: Requires skills in observation, communication, understanding visit components, and ensuring personal safety."]]}], "notes": "", "pics": 1}, {"n": 17, "title": "Working with Family: Home Visit", "blocks": [{"k": "list", "items": [[0, "Foundational Principles for the CH Nurse"], [0, "Non-Judgmental Practice:"], [1, "Work with all families (e.g., same-sex couples) without letting personal values conflict with professional responsibility."], [1, "Provide unbiased care to promote collective family health."], [0, "Ultimate Goal: Assist the family in becoming independent of services."], [0, "Move from focusing on family \"problems\" and \"needs\" to identifying family strengths (The Asset-Based Approach)"], [0, "Consider Existing Support: Ask \"Who did this before me?\" to avoid replacing natural support systems."], [0, "Practice Empathy: Reflect on how you would cope if you were in the family's situation."]]}], "notes": "", "pics": 1}, {"n": 18, "title": "Working with Families  “Home visits”", "blocks": [{"k": "list", "items": [[0, "Skills Used During Home Visits"], [0, "A) Essential Skills for the Home Visit"], [0, "A trusting relationship is key to a productive visit."], [0, "Required Skill Set:"], [1, "Expert interviewing & communication."], [1, "Relational skills (intuition, openness, compassion)."], [1, "Acute observational skills."], [0, "Overall Goal: Use these skills to promote nurturing relationships and stronger family health."]]}], "notes": "", "pics": 0}, {"n": 19, "title": "Working with Families  “Home visits”", "blocks": [{"k": "list", "items": [[0, "Skills Used During Home Visits"], [0, "B) Acute Observational Skills"], [0, "What to Observe: Everything! Both the family and their environment."], [0, "Key Areas of Focus:"], [1, "Neighborhood: Safety, general conditions."], [1, "Home Environment: Physical appearance, resources, barriers."], [1, "Family: Demeanor of all family members (present and absent), number of members. Nurse can inquire about absent members."], [0, "Purpose: This information helps you understand the family, identify patterns, and provide context for  their situation."]]}], "notes": "", "pics": 0}, {"n": 20, "title": "Working with Families  “Home visits”", "blocks": [{"k": "list", "items": [[0, "Skills Used During Home Visits"], [0, "C) Observing the Family: Nonverbal Cues"], [0, "Data Collection Starts Immediately: From the moment you knock on the door."], [0, "What to Look For:"], [1, "Body language, facial expressions, eye contact, gestures."], [0, "Action Steps:"], [1, "Acknowledge and greet everyone."], [1, "Use observations to open conversation (e.g., \"You seem anxious today...\")."]]}], "notes": "", "pics": 0}, {"n": 21, "title": "Working with Families  “Home visits”", "blocks": [{"k": "list", "items": [[0, "Skills Used During Home Visits"], [0, "D) The Nurse's Own Nonverbal Communication"], [0, "Nurse Are Also Being Observed: The family reads her/his body language closely."], [0, "Behaviors to Avoid:"], [1, "Fidgeting (e.g., keys): Signals nervousness or not wanting to be there."], [1, "Appearing rushed: Shows a lack of interest."], [1, "Minimal eye contact: Perceived as rude or unprofessional."], [1, "Refusing to sit or showing shock: Implies fear or judgment."]]}], "notes": "", "pics": 0}, {"n": 22, "title": "Components of the Family Home Visit", "blocks": [], "notes": "", "pics": 0}, {"n": 23, "title": "Components of the Family Home Visit", "blocks": [{"k": "list", "items": [[0, "1- Pre-visit preparation"], [0, "Triggered by a Referral: A request for service, which can be:"], [1, "Formal: From physicians, hospitals, social services."], [1, "Informal: From family, friends, or shelters."], [0, "Common Referral Examples:"], [1, "Follow-up for low-birth-weight babies or teen mothers."], [1, "Home assessment for a child returning to parents."], [1, "Checking on an elderly relative with health concerns."]]}], "notes": "", "pics": 0}, {"n": 24, "title": "Components of the Family Home Visit", "blocks": [{"k": "list", "items": [[0, "When calling for the first time, you, the PHN, will:"]]}, {"k": "list", "items": [[0, "Introduce yourself"], [0, "Explain the reason for the call"], [0, "Give the reason why the family was referred"], [0, "Indicate what the visit consists of"], [0, "Determine when a visit would be convenient for the family and you"], [0, "Get explicit directions to where the family is staying (the referral may have a different address, or the family did not mention that they are staying elsewhere)"], [0, "Repeat the date and time of the scheduled visit"]]}, {"k": "list", "items": [[0, "1- Pre-visit preparation"]]}], "notes": "", "pics": 1}, {"n": 25, "title": "Components of the Family Home Visit", "blocks": [{"k": "list", "items": [[0, "1- Pre-visit preparation"], [0, "Nurse's Toolkit:"], [1, "Contact info, educational materials, charting tools."], [1, "Resource directory, nursing bag/supplies."], [1, "Specialized supplies for specific visit types."], [0, "Managing Defensiveness: Be prepared to explain the purpose clearly:"], [1, "It's a routine service to support the transition home."], [1, "It's an opportunity for them to ask questions."], [1, "It's a free service provided by the agency (no direct cost)."]]}], "notes": "", "pics": 0}, {"n": 26, "title": "Components of the Family Home Visit", "blocks": [{"k": "list", "items": [[1, "Be Adaptable & Flexible: The visit's agenda may need to change based on new circumstances (e.g., a new baby arrives)."], [1, "Wellness-Oriented: Remember, clients often have higher levels of wellness than in acute care."], [1, "Collaborate Actively: Develop a sustained plan of care with the family."], [0, "Concluding the Visit Effectively:"], [1, "Review important points."], [1, "Emphasize and validate family strengths."], [1, "Plan together for the next visit."]]}, {"k": "list", "items": [[0, "2- Making the visit"]]}], "notes": "", "pics": 1}, {"n": 27, "title": "Components of the Family Home Visit", "blocks": [{"k": "list", "items": [[0, "The Balancing Act: Visit Length"], [0, "Too Short (< 20 mins):"], [1, "Insufficient for a thorough assessment."], [1, "Ideal for: Dropping supplies, relaying quick info, a brief check-in."], [0, "Too Long (> 60 mins):"], [1, "Avoid. Can be disruptive and unproductive."], [1, "Risks: Disrupts family routines, family may feel no value was gained, can lead to missed future visits."], [1, "Better Approach: Split lengthy assessments over two visits."], [1, "Key: Pick up on nonverbal cues to gauge the right time to end."]]}, {"k": "list", "items": [[0, "2- Making the visit"]]}], "notes": "", "pics": 1}, {"n": 28, "title": "Components of the Family Home Visit", "blocks": [{"k": "list", "items": [[0, "Immediate Post-Visit Actions:"], [1, "Say goodbye and pack up efficiently."], [1, "Prepare for your next visit while still in the community to demonstrate respect and professionalism."], [0, "Documentation (Charting):"], [1, "Gold Standard: Complete documentation immediately after the visit, before the next one."], [1, "Tools: Use agency-provided devices (laptop, tablet) for electronic health records."], [0, "Documentation Forms: Vary by agency but are designed for efficiency (e.g., checklists, coded care plans, narrative forms for specific assessments like postpartum visits)."]]}, {"k": "list", "items": [[0, "3- Concluding & Documenting the Visit"]]}], "notes": "", "pics": 1}, {"n": 29, "title": "Focus of the Family Home Visit", "blocks": [], "notes": "", "pics": 0}, {"n": 30, "title": "Focus of the Family Home Visit", "blocks": [{"k": "list", "items": [[0, "Tailored to Community Needs: Health departments design services based on local population data."], [0, "Example 1: High-Risk Maternal/Child Health"], [1, "Target: Communities with high rates of teen pregnancy or high-risk infants."], [1, "Interventions: Home/clinic visits for prenatal, postpartum, and newborn care education."], [1, "Guidance: Promotes well-baby visits, immunizations, and safety awareness."], [0, "Example 2: Aging Populations & Chronic Illness"], [1, "Target: Older adults or migrant workers."], [1, "Interventions: Teaching chronic disease management, enhanced nutrition, and fall/injury prevention."]]}], "notes": "", "pics": 0}, {"n": 31, "title": "Focus of the Family Home Visit", "blocks": [{"k": "list", "items": [[0, "Empowering Families: Teaching healthy living practices, even with chronic illness limitations."], [0, "Core Activities Include:"], [1, "Screening (e.g., hypertension, cholesterol)."], [1, "Physical assessments."], [1, "Nutrition and safety education."], [1, "Promotion of Immunization."], [0, "The Critical Role of Immunization:"], [1, "Protects individual and community health (\"herd immunity\")."], [1, "The nurse's role: Provide information, teach the importance of schedules, and conduct follow-up."]]}], "notes": "", "pics": 0}, {"n": 32, "title": "Personal Safety on the Home Visit  Personal Safety: A Professional Priority Safety is essential and must be balanced with maintaining respect, trust, and professionalism.", "blocks": [], "notes": "", "pics": 0}, {"n": 33, "title": "Personal Safety on the Home Visit", "blocks": [{"k": "list", "items": [[0, "Safety While Traveling"], [0, "Informing the Agency:"], [1, "Always leave a detailed itinerary with family contact info and your mobile number."], [0, "By Car:"], [1, "Full gas tank, GPS/map, addresses, and a cell phone."], [0, "By Public Transportation:"], [1, "Bus fare/schedule, knowledge of stops (to and from), and a cell phone."], [0, "General Rule: Always call the family ahead of time with your estimated arrival time."]]}], "notes": "", "pics": 0}, {"n": 34, "title": "Personal Safety on the Home Visit", "blocks": [{"k": "list", "items": [[0, "Safety Upon Arriving at the Home"], [0, "Verification is Critical: Do not enter until you are sure it's the right house and the correct family is home."], [0, "The Golden Rule: Do not enter if someone other than your identified client invites you in."]]}], "notes": "", "pics": 0}, {"n": 35, "title": "Personal Safety on the Home Visit", "blocks": [{"k": "list", "items": [[0, "Dealing with Challenging Situations: Family Conflict"], [0, "If an argument or physical fight breaks out:"], [1, "Immediately terminate the visit."], [1, "Calmly state that the distraction prevents the visit's purpose."], [1, "Inform them you will reschedule."], [1, "Calmly and quickly remove yourself from the home."], [0, "NEVER: Intervene, try to stop a fight, or act as a referee. You could become the next victim."], [0, "After Leaving: Use your observational skills to document the event for future assessment."]]}], "notes": "", "pics": 0}, {"n": 36, "title": "Personal Safety on the Home Visit", "blocks": [{"k": "list", "items": [[0, "Dealing with Challenging Situations: Intoxication & Strangers"], [0, "Family Members Under the Influence:"], [1, "Assess the situation. If the person is calm and in another room, you may continue."], [1, "Terminate the visit if the person is disruptive, abusive, or the situation feels volatile."], [1, "Reschedule for a time when the person is not under the influence. Never put yourself in the middle of a deteriorating situation."], [0, "Presence of Strangers:"], [1, "This may be the family's norm but can be distracting or make you uncomfortable."], [1, "Rely on observation and inquiry. Ask who they are and their relationship to the family."], [1, "Decide on inclusion: Determine if they should be included in the visit or if their presence indicates other family health needs."]]}], "notes": "", "pics": 0}, {"n": 37, "title": "Using of Nursing Process", "blocks": [{"k": "list", "items": [[0, "Family as A Client"]]}], "notes": "", "pics": 2}, {"n": 38, "title": "Nursing Process", "blocks": [], "notes": "", "pics": 1}, {"n": 39, "title": "Nursing ProcessFamily Health Assessment", "blocks": [{"k": "list", "items": [[0, "Data Collection Categories"]]}, {"k": "list", "items": [[1, "Family demographics, Physical environment, Psychological and spiritual environment, Family structure and roles, Family values and beliefs, Family communication patterns, Family health behavior, Family decision-making patterns, Family problem-solving patterns, Family coping patterns."]]}], "notes": "", "pics": 0}, {"n": 40, "title": "Nursing Process Family Health Assessment", "blocks": [{"k": "list", "items": [[0, "Assessment Methods"]]}], "notes": "", "pics": 0}, {"n": 41, "title": "Nursing Process Family Health Assessment", "blocks": [{"k": "list", "items": [[0, "Assessment Methods:"], [0, "2- formal approach: Examples"]]}], "notes": "", "pics": 0}, {"n": 42, "title": "Nursing Process Family Health Assessment", "blocks": [{"k": "list", "items": [[0, "2- Formal approach: Examples (Eco-map)"]]}, {"k": "list", "items": [[0, "A visual map of the family's connections with external systems in their environment."], [0, "Key Components:"], [1, "Central Circle: The family or a specific family member."], [1, "Peripheral Circles: Other people, organizations, and systems (e.g., work, school, healthcare)."], [1, "Connecting Lines: Depict the strength and nature of the relationships (e.g., strong, weak, stressful)."], [0, "Benefit: Depicts dynamic family-environment interactions and sources of support or stress."]]}], "notes": "", "pics": 1}, {"n": 43, "title": "Nursing Process Family Health Assessment", "blocks": [{"k": "list", "items": [[0, "2- Formal approach: Examples (Genogram)"]]}, {"k": "list", "items": [[0, "A visual diagram of the family's genealogy and relationships across generations."], [0, "Key Uses & Benefits:"], [1, "Reveals complex family patterns (e.g., hereditary diseases, relationship dynamics)."], [1, "Helps formulate hypotheses about family health over time."], [1, "Encourages family expression and storytelling."], [1, "Links health outcomes to preventive strategies based on identified risks."]]}], "notes": "", "pics": 1}, {"n": 44, "title": "Nursing Process Family Health Assessment", "blocks": [{"k": "list", "items": [[0, "Guidelines for Family Health Assessment"]]}], "notes": "", "pics": 0}, {"n": 45, "title": "Nursing Process  Family diagnosis process", "blocks": [], "notes": "", "pics": 0}, {"n": 46, "title": "Nursing Process  Family diagnosis process", "blocks": [{"k": "list", "items": [[0, "Identify the family health problems."], [0, "Determine what family members are directly and indirectly related to the problem."], [0, "Determine what factors from the external environment are related to the problem."], [0, "Describe the problem as it impacts the identified family members and external environment."], [0, "Indicate the risks that are associated with the problem(s)."], [0, "Prioritize the problems along with their risks with an emphasis on the problems that are overlapping and/or have overlapping risks."], [0, "2. Indicate the factors from the family (family unit and family members) and the external environment that are associated with the health problems."], [0, "3. Determine the measurements (quantitative and qualitative data) that confirm or verify the health problems."]]}], "notes": "", "pics": 0}, {"n": 47, "title": "Family NANDA 2024", "blocks": [{"k": "list", "items": [[0, "Ineffective family health self-management"], [0, "Risk for impaired attachment"], [0, "Disturbed family identity syndrome"], [0, "Risk for disturbed family identity syndrome"], [0, "Dysfunctional family processes"], [0, "Interrupted family processes"], [0, "Readiness for enhanced family processes"], [0, "Compromised family coping"], [0, "Disabled family coping"], [0, "Readiness for enhanced family coping"]]}], "notes": "", "pics": 0}, {"n": 48, "title": "NANDA Ex.", "blocks": [], "notes": "", "pics": 0}, {"n": 49, "title": "Nursing Process Family Care Planning", "blocks": [{"k": "list", "items": [[0, "Planning occurs when:"]]}], "notes": "", "pics": 0}, {"n": 50, "title": "Nursing Process  Family Care Planning", "blocks": [{"k": "list", "items": [[0, "The five areas of needs identified through nurse-family interactions are:"]]}], "notes": "", "pics": 0}, {"n": 51, "title": "Nursing Process  Family Care Planning", "blocks": [{"k": "list", "items": [[0, "Goals should be set mutually by nurse and the family member."], [0, "Each family is unique, and thus their care plan also."], [0, "Set realistic goals, according to time and resources and within limitations determined by the nurse employer/ organization."], [0, "Plan care according to family’s values and health care beliefs."], [0, "Coordinates with the health care team."]]}], "notes": "", "pics": 0}, {"n": 52, "title": "Nursing Process  Implementation", "blocks": [{"k": "list", "items": [[0, "Making Referrals"], [0, "Purpose: To connect the family with services beyond the agency's own resources."], [0, "Nurse's Responsibility:"], [1, "Have in-depth knowledge of community resources (official, voluntary, religious)."], [1, "Know eligibility requirements and service availability."], [0, "Contacting Resources"], [0, "The Nurse as a Connector: Knowing key personnel in agencies can help \"cut through red tape\" for families."], [0, "Building Rapport: Establishing relationships with agency staff helps:"], [1, "Secure services for families more effectively."], [1, "Expand the nurse's own database of available services for future referrals."], [0, "Empowering Families: The nurse can also give families pointers on how to procure services themselves."]]}], "notes": "", "pics": 0}, {"n": 53, "title": "Nursing Process  Family Health Evaluation", "blocks": [{"k": "list", "items": [[0, "Structure-Process Evaluation: How the visit was organized and conducted."], [0, "Outcome Evaluation: Whether the goals were achieved."], [0, "Self-Evaluation: The nurse's assessment of their own performance."]]}], "notes": "", "pics": 0}, {"n": 54, "title": "Nursing Process  Family Health Evaluation", "blocks": [{"k": "list", "items": [[0, "Structure-Process Evaluation"], [0, "Focus: The organization and flow of the visit itself."], [0, "What to Analyze:"], [1, "Resources & Environment: Timing, number of people present, materials used."], [1, "Nurse's Actions: Use of observational skills, adherence to standards."], [0, "Goal: Identify what to change or modify to make the next visit more effective and avoid distractions."]]}], "notes": "", "pics": 0}, {"n": 55, "title": "Nursing Process  Family Health Evaluation", "blocks": [{"k": "list", "items": [[0, "Outcome Evaluation"], [0, "Focus: Determining if the planned goals (outcomes) were met."], [0, "How it's Measured:"], [1, "Agency-Driven Criteria: Success based on specific expectations for a client type or visit."]]}], "notes": "", "pics": 0}, {"n": 56, "title": "Nursing Process  Family Health Evaluation", "blocks": [{"k": "list", "items": [[0, "Self-Evaluation & Peer Review"], [0, "Self-Evaluation:"], [1, "The nurse reflects on their own preparedness, data collection, and effectiveness."], [1, "Goal: Identify personal strengths and areas for improvement to enhance future practice."], [0, "Peer Evaluation:"], [1, "Another nurse observes a visit and provides feedback."]]}], "notes": "", "pics": 0}, {"n": 57, "title": "Case Study Analysis", "blocks": [{"k": "list", "items": [[0, "Family Profile:"], [0, "Family Name: R. Family"], [0, "Location: Small, rural community outside of the city. Nearest healthcare facility is 45 minutes away."]]}], "notes": "", "pics": 1}, {"n": 58, "title": "Case Study Analysis", "blocks": [{"k": "list", "items": [[0, "Household Members:"], [0, "Mother (A, 35 years old): Diagnosed with Type 2 diabetes and hypertension, non-compliant with medication due to financial difficulties."], [0, "Father (H, 40 years old): Works long hours in construction, has a history of smoking and persistent coughs but hasn’t visited a doctor in years due to lack of time and money."], [0, "Child 1 (S, 12 years old): Frequently misses school due to recurrent respiratory infections, sleeps in a shared, poorly ventilated bedroom with three younger siblings."], [0, "Child 2 (O, 9 years old): Struggles with obesity, likely due to a poor diet, which consists of mostly processed foods due to the family's financial constraints."], [0, "Child 3 (F, 6 years old): Appears healthy but is starting to show signs of behavioral issues, such as aggression at school, potentially linked to stressful family dynamics."]]}], "notes": "", "pics": 0}, {"n": 59, "title": "Case Study Analysis", "blocks": [{"k": "list", "items": [[0, "Environment:"], [0, "The R live in a small, crowded two-bedroom house in a low-income rural area. The home has minimal insulation and poor ventilation, which exacerbates S’s respiratory issues. The area has limited access to healthcare, fresh produce, and health education resources."], [0, "Referral Reason:"], [0, "The R family has been referred for a family health visit by a school nurse at S’s school, concerned about the overall health of the family and their limited access to healthcare. The school nurse reports that the children often appear undernourished, fatigued, and unkempt. The school nurse is also worried about the mother’s chronic conditions and her ability to care for the family, given her non-compliance with prescribed treatments."]]}], "notes": "", "pics": 0}, {"n": 60, "title": "Case Study Analysis", "blocks": [{"k": "list", "items": [[0, "Pre-Visit Preparation:"], [0, "How will you introduce yourself, explain the reason for the visit, and gather necessary information (e.g., health records, community resources) while addressing potential communication barriers and building rapport with the family?"], [0, "Making the Visit:"], [0, "How will you assess the health of each family member, prioritize health issues, and provide interventions considering the family's financial constraints and living conditions, while addressing behavioral and mental health concerns?"], [0, "Concluding and Documenting the Visit:"], [0, "What key information will you document, how will you ensure follow-up with the family given their barriers to healthcare access, and what action plan will you develop to support their ongoing care?"]]}], "notes": "", "pics": 0}, {"n": 61, "title": "Case Study Analysis", "blocks": [{"k": "list", "items": [[0, "Pre-Visit Preparation:"], [0, "How will you introduce yourself, explain the reason for the visit, and gather necessary information (e.g., health records, community resources) while addressing potential communication barriers and building rapport with the family?"], [0, "Making the Visit:"], [0, "How will you assess the health of each family member, prioritize health issues, and provide interventions considering the family's financial constraints and living conditions, while addressing behavioral and mental health concerns?"], [0, "Concluding and Documenting the Visit:"], [0, "What key information will you document, how will you ensure follow-up with the family given their barriers to healthcare access, and what action plan will you develop to support their ongoing care?"], [0, "Application of Nursing Process:"], [0, "How can the nursing process be applied to the Rahman family's case during the family health visit?"]]}], "notes": "", "pics": 0}, {"n": 62, "title": "References", "blocks": [{"k": "list", "items": [[0, "Rector, C. L. (2018). Community Health Nursing:  Promotion & Protecting the Public’s Health. 9th ed. Philadelphia: Wolters Kluwer Lippincott Williams and Wilkins."], [0, "Robinson, M., Coehlo, D. P., & Smith, P. S. (2022). Family health care nursing : theory, practice, and research (7th edition). F.A. Davis Company."]]}], "notes": "", "pics": 0}, {"n": 63, "title": "", "blocks": [], "notes": "", "pics": 1}]}, {"id": "M3", "en": "Epidemiology in Community Health Care", "ar": "علم الوبائيات في رعاية صحة المجتمع", "scenarios": ["S3"], "slides": [{"n": 1, "title": "Epidemiology in Community Health Care", "blocks": [{"k": "list", "items": [[0, "Course Code (title)"]]}, {"k": "list", "items": [[0, "2026-2027"]]}], "notes": "", "pics": 0}, {"n": 2, "title": "Objectives", "blocks": [{"k": "list", "items": [[0, "Explore epidemiology."], [0, "Explain the host, agent, and environment model."], [0, "Describe theories of causality in health and illness."], [0, "List the major sources of epidemiologic information."], [0, "Distinguish between incidence and prevalence in health and illness states."], [0, "Use epidemiologic methods to describe an aggregate’s health."]]}], "notes": "", "pics": 0}, {"n": 3, "title": "Epidemiology", "blocks": [{"k": "list", "items": [[0, "The word epi means among, and demos means people and logos study."], [0, "Epidemiology involves consideration of health problem in light of factors involved in its development."], [0, "The primary concern of epidemiology is  the health of groups of people."]]}], "notes": "", "pics": 1}, {"n": 4, "title": "Epidemiology", "blocks": [{"k": "list", "items": [[0, "Epidemiology is concerned with the distribution and determinants of health-related states  or events of health and illness in  specified human populations and the application of this study to the control of health problems. (USDHHS, 2012)."], [0, "Its is data driven and relies on an unbiased and systematic approach to collecting and analyzing and interpreting data."]]}], "notes": "", "pics": 1}, {"n": 5, "title": "Terminologies Frequently used in", "blocks": [], "notes": "", "pics": 1}, {"n": 6, "title": "Endemic", "blocks": [{"k": "list", "items": [[0, "Refers to the constant presence of a disease or infectious agent within a given geographic area or population group, without importation from outside.; may also refer to the “usual” or expected frequency of the disease within such area or population group. E.g. common cold."], [0, "An endemic can turn to an epidemic, e.g. typhoid fever."]]}], "notes": "", "pics": 0}, {"n": 7, "title": "Epidemics", "blocks": [{"k": "list", "items": [[0, "An epidemic refers to a disease occurrence that clearly exceeds the normal or expected frequency in a community or region."], [0, "“In past centuries, epidemics of cholera, bubonic plague, and smallpox swept through community after community, killing thousands of people, changing the community structure, and altering the lifestyle of masses of people”."]]}], "notes": "", "pics": 2}, {"n": 8, "title": "Pandemic", "blocks": [{"k": "list", "items": [[0, "When an epidemic, such as the bubonic plague (also called pneumonic plague or the Black Death) or HIV/AIDS, is worldwide in distribution, it is known as a pandemic."]]}], "notes": "", "pics": 1}, {"n": 9, "title": "Surveillance", "blocks": [{"k": "list", "items": [[0, "Continuous scrutiny of the factors that determine the occurrence and distribution of disease and other conditions of ill health."], [0, "The main purpose is to detect changes in trend or distribution in order to initiate investigative or control measures."], [0, "e.g. Surveillance for occurrence of Hepatitis B"]]}], "notes": "", "pics": 1}, {"n": 10, "title": "Concepts of Epidemiology", "blocks": [{"k": "list", "items": [[0, "Host, Agent, and Environment Model"], [0, "Causality"]]}], "notes": "", "pics": 0}, {"n": 11, "title": "Host, Agent, and Environment Model", "blocks": [{"k": "list", "items": [[0, "Through their early study of infectious diseases, epidemiologists began to consider disease states generally in terms of the epidemiologic triad, or the host, agent, and environment model."], [0, "Interactions among these three elements explained infectious and other disease patterns."]]}], "notes": "", "pics": 1}, {"n": 12, "title": "Host, Agent, and Environment Model", "blocks": [{"k": "list", "items": [[0, "Host"], [1, "Susceptible human or animal who harbors and nourishes a disease-causing agent"], [0, "Agent"], [1, "A factor that causes or contributes to a health problem or condition"], [0, "Environment"], [1, "All the external factors surrounding the host that might influence vulnerability or resistance"]]}], "notes": "", "pics": 1}, {"n": 13, "title": "Host", "blocks": [{"k": "list", "items": [[0, "Many physical, psychological, and lifestyle factors influence the host’s susceptibility and response to an agent."], [2, "Physical factors include age, sex, race, and genetic influences on the host’s vulnerability or resistance."], [2, "Psychological factors, such as outlook and response to stress, can strongly influence host susceptibility."], [2, "Lifestyle factors also play a major role. Diet, exercise, sleep patterns, and healthy or unhealthy habits all contribute to either increased or decreased vulnerability to the disease-causing agent (Fletcher & Fletcher, 2012)."]]}], "notes": "", "pics": 0}, {"n": 14, "title": "Agent", "blocks": [{"k": "list", "items": [[0, "Causative agents can be:"], [0, "Factors that are present (e.g., bacteria that cause tuberculosis, rocks on a mountain road that contribute to an automobile crash)."], [0, "Factors that are lacking (e.g., a low serum iron level that causes anemia or the lack of seat belt use that contributes to the extent of injury during an automobile crash)."]]}, {"k": "list", "items": [[0, "Agents vary considerably and include five types: biologic, chemical, nutrient, physical, and psychological."]]}], "notes": "", "pics": 1}, {"n": 15, "title": "Agent", "blocks": [{"k": "list", "items": [[0, "Biologic agents include bacteria, viruses, fungi, protozoa, worms, and insects. Some biologic agents are infectious, such as Influenza virus or HIV."], [0, "Chemical agents may be in the form of liquids, solids, gases, dusts, or fumes. Examples are poisonous sprays used on garden pests and industrial chemical wastes."], [0, "Nutrient agents include essential dietary components that can produce illness conditions if they are deficient or are taken in excess. For example, a deficiency of niacin can cause pellagra, and too much vitamin A can be toxic."], [0, "Physical agents include anything mechanical (e.g., chainsaw, automobile), material (e.g., rock slide), atmospheric (e.g., ultraviolet radiation), geologic (e.g., earthquake), or genetically transmitted that causes injury to humans."], [0, "Psychological agents are events that produce stress leading to health problems (e.g., war, terrorism)."]]}], "notes": "", "pics": 2}, {"n": 16, "title": "Agent", "blocks": [{"k": "list", "items": [[0, "Agents may also be classified as infectious or noninfectious."], [0, "Infectious agents cause communicable diseases, such as AIDS or tuberculosis—that is, the disease can be spread from one person to another."], [0, "Factors that influence the effect of the agent on the host"], [0, "Extent of exposure to the agent,"], [0, "the agent’s pathogenicity (capacity to cause disease in the host)"], [0, "Infectivity (capacity to enter the host and multiply)"], [0, "its virulence (severity of disease)"], [0, "Toxigenicity (capacity to produce a toxin or poison)"], [0, "Resistance (ability of the agent to survive environmental conditions)"], [0, "Antigenicity (ability to induce an antibody response in the host)"], [0, "Its structure and chemical composition"]]}], "notes": "", "pics": 0}, {"n": 17, "title": "Environment", "blocks": [{"k": "list", "items": [[0, "The physical environment includes factors such as geography, climate and weather, safety of buildings, water and food supply, and presence of animals, plants, insects, and microorganisms that have the capacity to serve as reservoirs (storage sites for disease-causing agents) or vectors (carriers) for transmitting disease."], [0, "The psychosocial environment refers to social, cultural, economic, and psychological influences and conditions that affect health, such as access to health care, cultural health practices, poverty, and work stressors, which can all contribute to disease or health (Fletcher & Fletcher, 2012)."]]}], "notes": "", "pics": 1}, {"n": 18, "title": "Epidemiologic triad. Epidemiologists study the causal agent, the susceptible host, and environmental", "blocks": [], "notes": "", "pics": 0}, {"n": 19, "title": "Causality", "blocks": [{"k": "list", "items": [[0, "The relationship between a cause and its effect"], [0, "to discover causal relationships, in order to understand why conditions, develop, and to offer effective prevention and protection (Fletcher & Fletcher, 2012)."]]}], "notes": "", "pics": 1}, {"n": 20, "title": "Causality", "blocks": [{"k": "list", "items": [[1, "Chain of causation"], [1, "Causation in noninfectious disease"], [1, "Multiple causation"], [1, "Web of causation"]]}], "notes": "", "pics": 1}, {"n": 21, "title": "Chain of Causation", "blocks": [], "notes": "", "pics": 0}, {"n": 22, "title": "Causation in noninfectious Disease", "blocks": [{"k": "list", "items": [[0, "Nine Criteria was developed to evaluate the relationship between environmental exposure and potential health outcomes"], [0, "Strength of association"], [0, "Consistency of association"], [0, "Specificity"], [0, "Temporality"], [0, "Biological gradient"], [0, "Biological plausibility"], [0, "Coherence of explanation"], [0, "Analogy"], [0, "Experiment evidence"]]}], "notes": "", "pics": 1}, {"n": 23, "title": "", "blocks": [], "notes": "", "pics": 1}, {"n": 24, "title": "Multiple Causation", "blocks": [{"k": "list", "items": [[0, "causation was never completely straightforward."], [0, "e.g., Even with long-recognized contagious diseases like cholera, the organism was only part of the equation. Factors such as availability of clean water, the number of trained nurses and doctors, the overall nutrition of the population, and even political upheaval could influence the spread of disease and the number who ultimately died”"]]}], "notes": "", "pics": 1}, {"n": 25, "title": "Web of Causation", "blocks": [{"k": "list", "items": [[0, "The implication that intervention (or breaking of the web at any point nearest to the disease) could profoundly impact the development of that disease."], [0, "Another common term used for this approach is causal matrix."]]}], "notes": "", "pics": 0}, {"n": 26, "title": "Causal Matrix for Infant Mortality", "blocks": [], "notes": "", "pics": 0}, {"n": 27, "title": "Web of Causation for Automobile Crash", "blocks": [], "notes": "", "pics": 0}, {"n": 28, "title": "Sources of Epidemiologic Information", "blocks": [], "notes": "", "pics": 0}, {"n": 29, "title": "Existing Data", "blocks": [{"k": "list", "items": [[0, "Vital statistics (births, deaths,, divorces, and marriages"], [0, "Census data (Population statistics)"], [0, "Reportable diseases"], [0, "Disease registries"], [0, "Environmental monitoring (Pesticides, industrial wastes, radioactive or nuclear materials, chemical additives in foods etc..)"], [0, "National Center for Health Statistics Health surveys"]]}], "notes": "", "pics": 0}, {"n": 30, "title": "https://www.moh.gov.bh/Content/Files/Publications/statistics/HS2020/hs2020_e.htm", "blocks": [], "notes": "", "pics": 0}, {"n": 31, "title": "Other Sources", "blocks": [{"k": "list", "items": [[0, "Informal observational studies"], [0, "Informal observational study often raises questions and suggests hypotheses that form the basis for designing larger-scale epidemiologic investigations"], [0, "Scientific studies"], [0, "The Cochrane Database of Systematic Reviews (CDSR) is the most popular resource for systematic reviews in health care and includes a section on public health"]]}], "notes": "", "pics": 1}, {"n": 32, "title": "Methods in Epidemiology", "blocks": [{"k": "list", "items": [[0, "Descriptive epidemiology:"], [0, "Includes investigations that seek to observe and describe patterns of health-related conditions that occurs naturally in a population"], [0, "Example"], [0, "“CHN might seek to learn how many children have been immunized against measles in a school district”"]]}], "notes": "", "pics": 0}, {"n": 33, "title": "Descriptive Methods  Counts", "blocks": [{"k": "list", "items": [[0, "simplest measure of description"], [0, "If a nurse discovers 50 cases of measles in an elementary school, that is a simple count."]]}], "notes": "", "pics": 1}, {"n": 34, "title": "Descriptive Methods  Incidence", "blocks": [{"k": "list", "items": [[0, "Incidence refers to all new cases of a disease or health condition appearing during a given time."], [0, "e.g. Three weeks after the start of a measles epidemic in a school, 20 New cases were identified. The incidence rate for that period is  (20”New Cases” /450” Population at risk”)"]]}], "notes": "", "pics": 0}, {"n": 35, "title": "Descriptive Methods  Prevalence", "blocks": [{"k": "list", "items": [[0, "Prevalence refers to all of the people with a particular health condition existing in a given population at a given point in time."], [0, "For instance, if the school has 500 students, the prevalence of measles on that day would be 10% (50 measles/500 population)."]]}], "notes": "", "pics": 0}, {"n": 36, "title": "", "blocks": [], "notes": "", "pics": 0}, {"n": 37, "title": "Methods in Epidemiology", "blocks": [{"k": "list", "items": [[0, "Analytic epidemiology"], [1, "Case–control studies: compares people who have a health or illness condition (number of cases with the condition) with those who lack this condition (controls)"], [1, "Cohort studies: A cohort study begins by selecting a group of people who display certain defined characteristics before the onset of the condition being investigated (Gordis, 2014). They would be observed over time to evaluate which variables were associated with the development or nondevelopment of the disease."]]}], "notes": "", "pics": 0}, {"n": 38, "title": "Methods in Epidemiology", "blocks": [{"k": "list", "items": [[0, "Experimental epidemiology:"], [0, "Experimental epidemiology follows and builds on information gathered from descriptive and analytic approaches."], [0, "In an experimental study, the investigator actually controls or changes the factors suspected of causing the health condition under study and then observes what happens to the health state (Merrill, 2013)."], [0, "In human populations, experimental studies should focus on disease prevention or health promotion rather than testing the causes of disease, which is done primarily on animals"]]}], "notes": "", "pics": 0}, {"n": 39, "title": "Practice:", "blocks": [{"k": "list", "items": [[0, "While collecting data in Jidhaf’s Health Centre, it was found:"], [0, "The total no. of breast cancer deaths reported among females is 5 during 2013. The total mid-year population of females is  146,400."], [0, "The total number of new diabetic cases reported  in adults last year was 487 and the old cases were 7890."], [0, "The total number of births were 11678 and the deaths were 899."], [0, "The estimated mid-year population is 267, 970. The total adult population is 1, 89, 780."]]}], "notes": "", "pics": 1}, {"n": 40, "title": "Calculate:", "blocks": [{"k": "list", "items": [[0, "Rate of breast cancer deaths in females"], [0, "Prevalence rate of diabetes"], [0, "Birth rate"], [0, "Death rate"]]}], "notes": "", "pics": 1}, {"n": 41, "title": "Thank you", "blocks": [], "notes": "", "pics": 0}]}, {"id": "M4", "en": "Immunity & Communicable Diseases", "ar": "المناعة والأمراض المعدية", "scenarios": ["S4"], "slides": [{"n": 1, "title": "Immunity & Communicable Diseases", "blocks": [{"k": "list", "items": [[0, "NUR415 – Family and Community Health Nursing Care"], [0, "Sep. 2025"]]}], "notes": "", "pics": 1}, {"n": 2, "title": "Objectives", "blocks": [{"k": "list", "items": [[0, "Define immunity and compare passive immunity, active immunity, cross-immunity, and herd immunity."], [0, "Explore recent regulations and statics of communicable diseases in Bahrain"], [0, "Explain the significance of immunization as a communicable disease control measure."], [0, "Discuss the role of community nurse toward immunizations"], [0, "Discuss different Measure of Safe Administration of Vaccines"]]}], "notes": "", "pics": 0}, {"n": 3, "title": "Immunity", "blocks": [{"k": "list", "items": [[0, "Immunity refers to a host’s ability to resist a particular infectious disease–causing agent."], [0, "This occurs when the body forms antibodies and lymphocytes that react with the foreign antigenic molecules and render them harmless"]]}], "notes": "", "pics": 1}, {"n": 4, "title": "Types of Immunity - Passive Immunity", "blocks": [{"k": "list", "items": [[0, "Passive immunity refers to short-term resistance that is acquired either naturally or artificially."], [0, "e.g. Newborns, through maternal antibody transfer, have natural passive immunity that lasts up to 1 year for certain diseases"], [0, "e.g. immune globulin (hepatitis A) used to boost a susceptible person’s immunity, and administration must be repeated periodically"]]}], "notes": "", "pics": 1}, {"n": 5, "title": "Types of Immunity - Active Immunity", "blocks": [{"k": "list", "items": [[0, "Active immunity is long-term and sometimes offers lifelong resistance that is acquired either naturally or artificially."], [0, "e.g. a person who contracts a disease develops long-lasting antibodies that provide immunity against future exposures."], [0, "e.g.  Artificially acquired active immunity is attained through vaccine inoculation. Like polio, diphtheria, smallpox vaccine"]]}], "notes": "", "pics": 1}, {"n": 6, "title": "Types of Immunity - Cross-Immunity", "blocks": [{"k": "list", "items": [[0, "Cross-immunity refers to a situation in which a person’s immunity to one agent provides immunity to a related agent as well."], [0, "e.g. Sometimes, infection with one disease, such as cowpox, gives immunity to a related disease, such as smallpox."]]}], "notes": "", "pics": 1}, {"n": 7, "title": "Types of Immunity - Herd Immunity", "blocks": [{"k": "list", "items": [[0, "Herd immunity describes the immunity level that is present in a population group."], [0, "a population with high herd immunity is one in which the immune people in the group outnumber the susceptible people"], [0, "Mandatory preschool immunizations and required travel vaccinations are applications of the herd immunity concept"], [0, "The immunity level needed for herd protection varies by disease, generally ranging from about 80% to over 90% depending on how contagious the disease is."]]}], "notes": "", "pics": 1}, {"n": 8, "title": "Communicable Diseases", "blocks": [{"k": "list", "items": [[0, "A communicable disease is caused by an infectious agent, such as a virus or bacteria, and can be transmitted from one source to another."], [0, "Knowledge of communicable diseases is fundamental to the practice of community/public health nursing because these diseases typically spread through communities of people"]]}], "notes": "", "pics": 1}, {"n": 9, "title": "Modes of Transmission", "blocks": [{"k": "list", "items": [[0, "Communicable diseases spread through direct or indirect transmission."], [0, "Direct transmission: person-to-person or animal-to-human contact."], [0, "Indirect transmission: spread through a reservoir such as a vector, contaminated food or water, or airborne particles."], [0, "Vectors (e.g., insects) may transmit disease mechanically, carried on the body, or biologically, after the organism multiplies within the vector."]]}], "notes": "", "pics": 1}, {"n": 10, "title": "Foodborne & Waterborne Illness", "blocks": [{"k": "list", "items": [[0, "Food- or water-related illness results from either infection (a pathogen multiplies in the GI tract) or intoxication (a bacterial toxin is ingested)."], [0, "Contamination can occur at the source, through unsanitary handling, or from improper storage temperatures."], [0, "The time between exposure and symptom onset is called the incubation period."], [0, "Core prevention: handwashing, thorough cooking, safe storage and reheating, and avoiding cross-contamination between raw and cooked food."]]}], "notes": "", "pics": 1}, {"n": 11, "title": "", "blocks": [], "notes": "", "pics": 0}, {"n": 12, "title": "Prevention of communicable diseases", "blocks": [{"k": "list", "items": [[0, "In the context of communicable disease control, two approaches are useful in achieving primary prevention:"], [0, "immunizations"], [0, "education using mass media with targeted health messages to aggregates."]]}], "notes": "", "pics": 1}, {"n": 13, "title": "Immunization & Vaccination", "blocks": [{"k": "list", "items": [[0, "The extended life expectancy that has been enjoyed during the 20th century was largely due to the expansion of immunization programs that are provided to families"]]}, {"k": "list", "items": [[0, "Immunization: A process by which a person becomes protected against a disease through vaccination. This term is often used interchangeably with vaccination or inoculation"], [0, "Vaccination: The act of introducing a vaccine into the body to produce protection from a specific disease"]]}], "notes": "", "pics": 1}, {"n": 14, "title": "Types of Vaccines", "blocks": [{"k": "list", "items": [[0, "Vaccines are prepared from either a live organism or an inactivated form of the organism."], [0, "Live attenuated vaccines use a weakened organism that can still replicate, producing a strong immune response from a small dose."], [0, "Inactivated vaccines use an organism inactivated by heat or chemicals; it cannot replicate in the recipient."], [0, "Vaccine type influences the recommended dosing schedule and storage requirements."]]}], "notes": "", "pics": 1}, {"n": 15, "title": "Vaccine Preventable Diseases (VPD)", "blocks": [], "notes": "", "pics": 1}, {"n": 16, "title": "Role of Community Health Nurse", "blocks": [], "notes": "", "pics": 0}, {"n": 17, "title": "C/PHN Role in Disease Investigation & Reporting", "blocks": [{"k": "list", "items": [[0, "Reportable diseases must be reported to the local or state health department; select diseases are then voluntarily shared with the CDC as notifiable diseases."], [0, "Reporting is generally an obligation of physicians, nurses, dentists, veterinarians, pharmacists, and administrators of hospitals, schools, and nursing homes."], [0, "Investigation steps: identify others who may be infected, determine the source and mode of transmission, identify at-risk contacts for screening, prevent further transmission, and monitor the response."], [0, "Interviews should be conducted with a neutral, nonjudgmental approach and assurance of confidentiality."]]}], "notes": "", "pics": 1}, {"n": 18, "title": "Disease Surveillance & Control", "blocks": [{"k": "list", "items": [[0, "Surveillance is the ongoing, systematic collection, analysis, and interpretation of health data (WHO)."], [0, "Surveillance enables early identification of public health emergencies and evaluation of intervention effectiveness."], [0, "Contact tracing identifies additional people who may have been exposed."], [0, "Disease control measures may include testing, counseling, education, environmental modification, vaccination, treatment, or prophylaxis."]]}], "notes": "", "pics": 1}, {"n": 19, "title": "Factors Influencing Vaccine Timing", "blocks": [{"k": "list", "items": [[0, "Age-specific risk of the disease itself."], [0, "Age-specific risk of complications from the disease."], [0, "Ability of a person at a given age to mount an adequate and lasting immune response."], [0, "Potential interference from passively transferred maternal antibodies."]]}], "notes": "", "pics": 1}, {"n": 20, "title": "Immunizations Schedule", "blocks": [], "notes": "", "pics": 1}, {"n": 21, "title": "Immunizations Schedule", "blocks": [], "notes": "", "pics": 1}, {"n": 22, "title": "Vaccine Hesitancy: Addressing Parents’ Concerns", "blocks": [{"k": "list", "items": [[0, "“Are the vaccines safe?” – explain the required safety trials and how to manage possible side effects."], [0, "“Why so many vaccines at once?” – reassure that vaccine antigen exposure is far less than everyday environmental exposure."], [0, "“Why give vaccines so young?” – explain that early protection reduces the window of vulnerability to serious disease."], [0, "Nurses should provide accurate, evidence-based information, since online misinformation can strongly influence parents’ vaccination decisions."]]}], "notes": "", "pics": 1}, {"n": 23, "title": "Safe Administration of Vaccines", "blocks": [], "notes": "", "pics": 1}, {"n": 24, "title": "Administering Vaccines", "blocks": [], "notes": "", "pics": 1}, {"n": 25, "title": "Possible Vaccine Side Effects", "blocks": [], "notes": "", "pics": 0}, {"n": 26, "title": "General Vaccine Contradictions - MOH", "blocks": [{"k": "list", "items": [[0, "The vaccine is contraindicated in case of severe allergic reaction to vaccine component following a prior dose."], [0, "Fitness certificate from treating physician is recommended for immunocompromised and cancer patients."], [0, "Moderate to severe illness at the time of vaccination."], [0, "BCG vaccination should not be given to persons who are immunosuppressed"]]}], "notes": "", "pics": 1}, {"n": 27, "title": "Vaccine Routes and sites", "blocks": [{"k": "list", "items": [[0, "Each vaccine has a recommended administration route and site. This information is included in the manufacturer’s package."], [0, "Deviation from the recommended route may reduce vaccine efficacy or increase local adverse reactions."]]}], "notes": "", "pics": 2}, {"n": 28, "title": "Managing Acute Vaccine Reactions", "blocks": [{"k": "list", "items": [[0, "measures should be taken to prevent injuries if a patient becomes weak or dizzy or loses consciousness"], [0, "Have the patient seated."], [0, "Be aware of symptoms that precede fainting (e.g., weakness, dizziness, pallor)."], [0, "Provide supportive care and take appropriate measures to prevent injuries if such symptoms occur."], [0, "Observe recipients after vaccination to decrease the risk for injury should they faint. For most vaccines a 15-minute observation period is recommended."]]}], "notes": "", "pics": 1}, {"n": 29, "title": "Thank you", "blocks": [], "notes": "", "pics": 1}]}, {"id": "M5", "en": "Transcultural Nursing", "ar": "التمريض عبر الثقافي", "scenarios": ["S5"], "slides": [{"n": 1, "title": "Transcultural Nursing     2025-2026", "blocks": [], "notes": "", "pics": 1}, {"n": 2, "title": "Objectives", "blocks": [{"k": "list", "items": [[0, "By the end of the session, the student will be able to:"], [0, "Define the concept of culture"], [0, "Discuss the meaning of cultural diversity, ethnocentrism, ethnorelativism and their effects on community health nursing practice."], [0, "Identify the five characteristics shared by all culture."], [0, "Discuss the major views in the world culture."], [0, "Discuss the health-related values, beliefs and practices of selected culturally diverse population (Activity)."], [0, "Identify the guidelines for nurses working with all immigrant groups."], [0, "Apply principles of transcultural nursing in community health nursing principles."]]}], "notes": "", "pics": 1}, {"n": 3, "title": "The Meaning of Culture", "blocks": [{"k": "list", "items": [[0, "Culture: refers to the beliefs, values, and behaviours that are shared by members of a society and provide a template or “road map” for living"], [0, "design for living; it provides a set of norms and values that offer stability and security for members of a society."], [0, "It forms the basis for the definitions of male and female roles."]]}], "notes": "", "pics": 1}, {"n": 4, "title": "Cultural Diversity", "blocks": [{"k": "list", "items": [[0, "Cultural diversity, also called cultural plurality, means that a variety of cultural patterns coexist within a designated geographic area."]]}], "notes": "", "pics": 1}, {"n": 5, "title": "", "blocks": [], "notes": "", "pics": 1}, {"n": 6, "title": "Cultural Diversity", "blocks": [{"k": "list", "items": [[0, "Race:"], [0, "Biologically designated groups of people whose distinguishing features, such as skin color."], [0, "Ethnic group:"], [0, "Collection of people who have common origins and a shared culture and identity; they may share a common geographic origin, race, language, religion, traditions, values, and food preferences (Spector, 2013)."]]}], "notes": "", "pics": 1}, {"n": 7, "title": "Question #1", "blocks": [{"k": "list", "items": [[0, "Is the following statement true or false?"], [0, "“Race and ethnicity are interchangeable terms”."]]}], "notes": "", "pics": 1}, {"n": 8, "title": "Answer to Question #1", "blocks": [{"k": "list", "items": [[0, "False"], [0, "Rationale: Race refers to biologically designated groups of people whose distinguishing features are inherited. Ethnicity refers to a group of qualities that mark a person’s association with a particular ethnic group or who share cultural and/or physical characteristics."]]}], "notes": "", "pics": 1}, {"n": 9, "title": "Ethnocentrism", "blocks": [{"k": "list", "items": [[0, "Ethnocentrism:"], [0, "Bias that person’s own culture is best, and others are wrong or inferior"], [0, "Can block effective communication by creating biases and misconceptions about human behavior."], [0, "This can cause serious damage to interpersonal relationships and interfere with the effectiveness of nursing interventions"]]}], "notes": "", "pics": 1}, {"n": 10, "title": "Ethnorelativism", "blocks": [{"k": "list", "items": [[0, "Seeing all behavior in a cultural context."]]}], "notes": "", "pics": 1}, {"n": 11, "title": "Cultural Sensitivity Continuum", "blocks": [{"k": "list", "items": [[0, "Cross-cultural sensitivity continuum. Being extremely ethnocentric (left of midpoint) and totally ethnorelative (far right) are reflected in the diagram."], [0, "The steps toward ethnorelativism begin at the most ethnocentric view, with refusal and resistance. Neutrality is midpoint, and adjustment and incorporation bring the person to an ethnorelative perspective."]]}], "notes": "", "pics": 0}, {"n": 12, "title": "Characteristics of Culture", "blocks": [{"k": "list", "items": [[0, "1. Culture is Learned"], [0, "Patterns of cultural behavior are acquired, not inherited or genetically determined."], [0, "Each person learns about culture through socialization with the family or significant group, a process called enculturation."]]}], "notes": "", "pics": 1}, {"n": 13, "title": "Characteristics of Culture", "blocks": [{"k": "list", "items": [[0, "2. Culture is integrated"], [0, "All parts of a culture are interrelated and interdependent."], [0, "The various components of a culture (social mores or religious beliefs), perform separate functions but come into relative harmony with each other to form an operating and cohesive whole."], [0, "Any examples??"], [0, "Parents who are Jehavo’s Witnesses may refuse a blood transfusion for their child. This choice represents behavior consistent with their cultural values and standards. The single behavior of refusing blood transfusions, when viewed in context, is seen to be part of a larger religious belief system and a basic component of the parents’ culture."]]}], "notes": "", "pics": 1}, {"n": 14, "title": "Characteristics of Culture", "blocks": [{"k": "list", "items": [[0, "3. Culture is Shared"], [0, "Individuals practice a culture, phenomena shared by all members of the group and is transmitted from generation to generation."]]}], "notes": "", "pics": 1}, {"n": 15, "title": "Characteristics of Culture", "blocks": [{"k": "list", "items": [[0, "4. Culture is Generally Tacit"], [0, "Culture provides a guide for human interaction that is tacit—unexpressed and at the unconscious level."], [0, "Culture provides an implicit set of cues for behavior, not a written set of rules."], [0, "It is like a memory bank in which knowledge is stored for recall when the situation requires it."], [0, "Any examples??"], [0, "Culture teaches"], [0, "how close to stand when talking with someone"], [0, "how one should appropriately respond to older adults."]]}], "notes": "", "pics": 1}, {"n": 16, "title": "Characteristics of Culture", "blocks": [{"k": "list", "items": [[0, "5. Culture is Dynamic"], [0, "Culture undergoes change; none is entirely static."], [0, "Some members generate innovations, see advantages in doing things differently and are willing to adopt new practices."], [0, "When this adaptation does not occur, the cultural group may face serious difficulty."], [0, "The lack of familiarity can result in conflicting feeling that have been termed Culture shock"]]}], "notes": "", "pics": 1}, {"n": 17, "title": "World community", "blocks": [{"k": "list", "items": [[0, "Beliefs about the causes and effects of illness, health practices, and health-seeking behaviors are all influenced by a person’s, a group’s, or a community’s perception of what causes illness and injury and what actions can best treat or cure the health problem."], [0, "The three major views in the world community are:"], [0, "Biomedical."], [0, "Magicoreligious."], [0, "Holistic health beliefs"]]}], "notes": "", "pics": 2}, {"n": 18, "title": "World community", "blocks": [{"k": "list", "items": [[1, "Other views"], [1, "Folk medicine and home remedies"], [1, "Herbalism"], [1, "Prescription and over-the-counter drugs"]]}], "notes": "", "pics": 2}, {"n": 19, "title": "Biomedical", "blocks": [{"k": "list", "items": [[0, "Relies on scientific principles and sees diseases and injuries as life events controlled by physical and biochemical processes that can be manipulated through medication, surgery, and other treatments."], [0, "Ex. Disease causes illness, which has a specific cause and a set of treatment requirements."]]}], "notes": "", "pics": 1}, {"n": 20, "title": "Magicoreligious", "blocks": [{"k": "list", "items": [[0, "Magicoreligious focus on the control of health and illness by supernatural forces."], [0, "Diseases occur as a result of “committing sins” or “going against God’s will.”"], [0, "Good health is a gift from God, and illness is a form of punishment that affords an opportunity to be forgiven and to realign oneself with God."]]}], "notes": "", "pics": 1}, {"n": 21, "title": "Holistic", "blocks": [{"k": "list", "items": [[0, "View the world as being in harmonious balance. imbalance of natural forces can create chaos and disease."], [0, "For an individual to be healthy, all facets of the individual’s nature—physical, mental, emotional, and spiritual—must be in balance."], [0, "Ex. Considering that infectious disease such as tuberculosis is not only caused by an organism but also by the environment, malnutrition, and poverty"]]}], "notes": "", "pics": 1}, {"n": 22, "title": "Folk medicine and home remedies", "blocks": [{"k": "list", "items": [[0, "Folk medicine is a body of preserved treatment practices that has been handed down verbally from generation to generation."], [0, "Exists as a first line of treatment."], [0, "Any examples??"], [0, "“Taping coins over a newborn’s umbilical area to prevent hernias”"]]}], "notes": "", "pics": 2}, {"n": 23, "title": "Herbalism", "blocks": [{"k": "list", "items": [[0, "Herbs are not regulated as drugs and are not risk free."], [0, "Dosages are not standardized and are left to the individual."], [0, "Quality of the product may be suspect."], [0, "Herbs must be used only in moderation and with caution, preferably with guidance by a health care practitioner."]]}], "notes": "", "pics": 1}, {"n": 24, "title": "Prescription and over-the-counter drugs", "blocks": [{"k": "list", "items": [[0, "OTC are not risk free."], [0, "The safety and efficacy of medications must be assessed."]]}], "notes": "", "pics": 1}, {"n": 25, "title": "Question #2", "blocks": [{"k": "list", "items": [[0, "Which would characterize a culture?"], [1, "Inherited"], [1, "Static"], [1, "Individualized"], [1, "Tacit"]]}], "notes": "", "pics": 1}, {"n": 26, "title": "Answer to Question #2", "blocks": [{"k": "list", "items": [[0, "D. Tacit"], [0, "Rationale: Culture is learned, integrated, shared, mostly tacit, and dynamic."]]}], "notes": "", "pics": 1}, {"n": 27, "title": "Activity:  Select a  Cultural Community and discuss the following:", "blocks": [{"k": "list", "items": [[1, "Population characteristics and culture"], [1, "Health problems"], [1, "Health beliefs and practices"]]}], "notes": "", "pics": 1}, {"n": 28, "title": "Example:  Arab Populations and Muslims", "blocks": [], "notes": "", "pics": 1}, {"n": 29, "title": "", "blocks": [{"k": "table", "rows": [["Population Characteristics and Culture:\n\nA common language (Arabic).\nArabs are largely Christian or Muslim, although some Arabs may be Jews or Druze.\nArabs generally value Western medicine, trust health care workers, and do not generally postpone seeking medical care\nMany Arabic women stay at home and are not in the workforce. \nFamilies impose stricter rules for girls than for boys. \nAfter menarche, teenage girls may not socialize with boys. \nThe adolescent female also begins to cover her head and perhaps wears a hajab, which takes the form of a modest dress and veil designed to diminish attractiveness and appeal to the opposite sex. Some Arab groups take this mode of dress to extremes, not even allowing a woman’s eyes to show out of the hajab. Modesty is one of the core values for Arabs; it is expressed by both genders, although more evidently by females.\nAll sexual contacts outside the marital bond are considered illegal."]]}], "notes": "", "pics": 1}, {"n": 30, "title": "Health Problems", "blocks": [{"k": "list", "items": [[0, "Health problems among Middle Easterners are most frequently lifestyle related. These include poor nutritional practices, resulting in obesity, especially among women; smoking among men; and lack of physical exercise"], [0, "In some rural areas, especially in Saudi Arabia, men and women chew tobacco, and an increase of oral cancers is seen."], [0, "Major public health concerns for most Arabs are related to motor vehicle accidents, maternal–child health, TB, malaria, trachoma, typhus, hepatitis, typhoid fever, dysentery, and parasitic infection."], [0, "Most social restrictions are directed toward women and can affect their health. pregnancy can be complicated by genital mutilation, with infections and difficult deliveries."], [0, "Childbearing continues up until menopause. There is often a desire to have more sons than daughters, and this may result in very large families and closely spaced pregnancies—often without the benefit of family planning."], [0, "Abortion and infanticide are not accepted."]]}], "notes": "", "pics": 1}, {"n": 31, "title": "Health Beliefs and Practices", "blocks": [{"k": "list", "items": [[0, "Traditional medicine is practiced in spite of the growth of Western medical services in some of the richer Arab nations."], [0, "Traditional health care practices are much more common in the poorer Middle Eastern countries and in rural areas of all Arabic countries."], [0, "Muslims believe in predestination—that life is determined beforehand—and they attribute the occurrence of disease to the will of Allah. However, this does not prevent people from seeking medical treatment."], [0, "Islamic law prohibits the use of illicit drugs, which include alcohol. Users of such substances are liable to trial, and those convicted of smuggling substances into an Arab country can be sentenced to death in some cases."], [0, "Sharaf, or honor, is an important concept in Arab American beliefs, and drug addiction, mental illness, or unwed pregnancy of a family member brings shame to the entire family. Conversely, when a member does something good or is recognized for an achievement, that honor is reflected on the family as a whole."]]}], "notes": "", "pics": 1}, {"n": 32, "title": "Health Beliefs and Practices", "blocks": [{"k": "list", "items": [[0, "Cleanliness is paramount and ritualistic, especially before prayers and after sexual intercourse. The bodies of both genders are kept free of axillary and pubic hair. The left hand is used for cleaning the genitals and the right one is reserved for eating, hand shaking, and other hygienic activities."], [0, "Muslims fast during Ramadan from sunrise to sunset, and this can include abstinence from all things (including medications or intravenous fluids). Illness can be an exception to this rule, but public health nurses should consult with a family elder or Muslim leader to encourage the client to continue with any necessary treatments."], [0, "Also, Muslims pray several times daily, facing toward Mecca. Home visits should be planned so that prayers are not interrupted."], [0, "When caring for Arabs in clinics or at home, a nurse of the same sex as the client should be assigned. It is important to note that only women may discuss many topics (e.g., menstruation, family planning, pregnancy, and childbirth), and men are not included in these discussions."]]}], "notes": "", "pics": 1}, {"n": 33, "title": "Guidelines for nurses working with groups", "blocks": [], "notes": "", "pics": 0}, {"n": 34, "title": "Guidelines for nurses working with groups", "blocks": [], "notes": "", "pics": 1}, {"n": 35, "title": "TRANSCULTURAL COMMUNITY HEALTH NURSING PRINCIPLES", "blocks": [], "notes": "", "pics": 3}, {"n": 36, "title": "Transcultural Nursing Principles", "blocks": [], "notes": "", "pics": 1}, {"n": 37, "title": "Develop Cultural Self-Awareness", "blocks": [{"k": "list", "items": [[0, "Recognizing the values, beliefs, and practices that make up one’s own culture."], [0, "To gain skill in understanding their own culturally based behavior, nurses can complete a cultural self-assessment by analyzing their own:"], [1, "Influences related to racial background"], [1, "Verbal and nonverbal communication patterns"], [1, "Values and norms (expected cultural practices or behaviors)"], [1, "Beliefs and practices"]]}], "notes": "", "pics": 1}, {"n": 38, "title": "Cultivate Cultural Sensitivity", "blocks": [{"k": "list", "items": [[0, "Cultural sensitivity requires recognizing that culturally based values, beliefs, and practices influence people’s health and lifestyles and need to be considered in plans for service."]]}], "notes": "", "pics": 1}, {"n": 39, "title": "Assess the Client Group’s Culture", "blocks": [{"k": "list", "items": [[0, "Transcultural Assessment Model showing the culturally diverse individual through communication, space, social organization, time, environmental control, and biologic variations. (Adapted from Giger, J. M. (2017)."]]}], "notes": "", "pics": 1}, {"n": 40, "title": "Cultural Assessment", "blocks": [{"k": "list", "items": [[0, "Ethnic/racial background"], [0, "Language and communication patterns"], [0, "Cultural values and norms"], [0, "Biocultural factors"], [0, "Religious beliefs and practices"], [0, "Health beliefs and practices"]]}], "notes": "", "pics": 1}, {"n": 41, "title": "Show Respect and Patience While Learning About Other Cultures", "blocks": [{"k": "list", "items": [[0, "Attentive listening is a way to show respect and to learn about a client’s culture."]]}], "notes": "", "pics": 1}, {"n": 42, "title": "Examine Culturally Derived Health Practices", "blocks": [{"k": "list", "items": [[0, "Examine the cultural practices affecting health"], [0, "Are these behaviors preserving or enhancing the group’s health"], [0, "A cultural practice can be modified or continued while respecting the culture is maintained."]]}], "notes": "", "pics": 2}, {"n": 43, "title": "Dominant Values", "blocks": [{"k": "list", "items": [[0, "Dominant values – the beliefs and sanctions of the dominant or majority culture"], [0, "In the US, the majority culture is non-Hispanic Whites; dominant values have largely included the work ethic, thrift, success, independence, initiative, privacy, cleanliness, attractive appearance, and a focus on the future"], [0, "Awareness of dominant values matters in nursing – it helps explain why some client behaviors are accepted by health professionals and others are not, and why persuading clients to adopt new ways of thinking can be difficult"], [0, "Dominant values can and do change as demographics shift – the US is projected to become a majority–minority nation by mid-century as current minority groups grow in population"]]}], "notes": "", "pics": 0}, {"n": 44, "title": "Subcultures & Microcultures", "blocks": [{"k": "list", "items": [[0, "Subcultures"], [0, "Smaller cultural groups within a larger society, developed and preserved to meet the unique needs, values, and beliefs of their members"], [0, "Distinguished by shared characteristics such as ethnicity, occupation, socioeconomic status, religion, geographic area, age, gender, or sexual preference"], [0, "Microcultures"], [0, "Even smaller groups who share specific experiences or special cultural knowledge unique to the subgroup (e.g., recent refugees sharing resources, third-generation immigrants sharing food and traditions)"], [0, "Also include groups on the margins of mainstream culture with their own ways of coping (e.g., migrant farm workers, urban homeless families, gangs)"], [0, "Related Concepts"], [0, "Intraethnic variations – differences within a microculture due to social class, socioeconomic status, age, or degree of acculturation"], [0, "Minority group – part of a population that differs from the majority and often receives different and unequal treatment"]]}], "notes": "", "pics": 0}, {"n": 45, "title": "Key Transcultural Concepts", "blocks": [{"k": "list", "items": [[0, "Transcultural (cross-cultural) nursing – providing culturally sensitive nursing service to people of an ethnic or racial background different from the nurse's"], [0, "Cultural relativism – recognizing and respecting alternative viewpoints and understanding values, beliefs, and practices within their own cultural context"], [0, "Cultural brokering – mediating or building connections between people from different cultural backgrounds to promote change"], [0, "Cultural conflict – a perceived threat arising from a misunderstanding of expectations between clients and nurses when either group is unaware of cultural differences"], [0, "Cultural adaptation – the successful adjustment to cultural changes, often following a period of culture shock"]]}], "notes": "", "pics": 0}, {"n": 46, "title": "Cultural Diversity & Immigration in the US", "blocks": [{"k": "list", "items": [[0, "Immigration has been a major driver of cultural diversity in the US, from early Indigenous peoples and European settlers to enslaved Africans and generations of refugees and immigrants"], [0, "Key immigration laws shaped current diversity – medical/economic inspections (1891), the Immigration Act of 1924 (limited immigration by national origin), the 1965 Act (ended quotas, endorsed family migration), the Immigration Reform and Control Act of 1986, and the Immigration Act of 1990"], [0, "Current trends – a large undocumented population, rapid growth of multiracial and Asian populations, and fast-growing Hispanic/Latino communities"], [0, "Ongoing issues – ambivalence toward accepting refugees, family separation at the border, and increased border enforcement continue to shape the social climate for immigrants"]]}], "notes": "", "pics": 0}, {"n": 47, "title": "Integrated Health Care & CAM", "blocks": [{"k": "list", "items": [[0, "Complementary and alternative medicine (CAM) – a broad, multibillion-dollar array of healing resources used to promote comfort, health, and well-being"], [0, "Therapies – juice diets, fasting, coffee enemas, biofeedback"], [0, "Exercise activities – T'ai chi, yoga, dance"], [0, "Exposure – aromatherapy, music therapy, light therapy"], [0, "Manipulation – acupuncture, acupressure, chiropractic, cupping, reflexology"], [0, "Integrated health care – combining complementary therapies with Western medicine (e.g., for pain relief in labor or to improve sleep in the ICU); nurses stay informed, remain objective, and weigh pros and cons when a therapy conflicts with medical advice"]]}], "notes": "", "pics": 0}, {"n": 48, "title": "Role & Preparation of the C/PHN", "blocks": [{"k": "list", "items": [[0, "To be an effective advocate, the nurse must:"], [0, "Speak knowledgeably about health care practices and choices"], [0, "Assess the client or family adequately to know what belief system motivates their choices"], [0, "Teach clients about the limits and benefits of cultural health care practices"], [0, "Individualize assessment and caregiving within the client's culture, rather than generalizing based on group norms"], [0, "Nurses can prepare by:"], [0, "Performing a cultural self-assessment to identify their own beliefs and biases"], [0, "Learning from peers from the same cultural group as their clients"], [0, "Attending workshops or conferences on transcultural nursing and cultural ethics"], [0, "Reading about ethnocultural and alternative health care practices, talking with clients about their views, and attending community cultural events"]]}], "notes": "", "pics": 0}, {"n": 49, "title": "Cross-Cultural Guidelines for Practice", "blocks": [{"k": "list", "items": [[0, "Know your own belief system and values, and acknowledge that cultural differences may exist"], [0, "Build a basic understanding of other cultures without stereotyping or assuming you understand what any one person thinks or feels"], [0, "Show genuine interest, suspend judgment, and work to establish trust"], [0, "Respect power imbalances, status hierarchy, and gender and age differences within the family or group"], [0, "Improve cross-cultural communication skills – use clear, simple language and avoid jargon or slang"], [0, "Attend to unspoken communication and appropriate body language; practice active listening"], [0, "Don't assume understanding – clarify and seek feedback to confirm the message was understood"], [0, "Apologize for cultural mistakes and show willingness to learn"], [0, "Use trained interpreters and deliver information in the client's preferred language whenever possible"], [0, "Assess immigration history, refugee stress or trauma, acculturation gaps, and experiences of discrimination"]]}], "notes": "", "pics": 0}, {"n": 50, "title": "Harmful vs. Helpful Cultural Practices", "blocks": [{"k": "list", "items": [[0, "Some traditional practices promote physical and psychological health (customary diet, birth rituals, certain folk remedies)"], [0, "Other practices are neither harmful nor health-promoting but are important for preserving cultural identity and security"], [0, "Some traditional practices can be directly harmful, such as relying solely on herbal poultices to treat an infected wound instead of antibiotics, “burning” the abdomen to compensate for heat loss from diarrhea, or using Greta or Azarcon (lead-containing Hispanic remedies for stomach discomfort)"], [0, "Harmful practices are best addressed by discussing concerns with group leaders and healers, while respecting the group's norms for authority and decision-making"]]}], "notes": "", "pics": 0}, {"n": 51, "title": "Question #3", "blocks": [{"k": "list", "items": [[0, "Is the following statement true or false?"], [0, "“The first step that a nurse does when applying transcultural nursing principles is to cultivate cultural sensitivity”"]]}], "notes": "", "pics": 1}, {"n": 52, "title": "Answer to Question #3", "blocks": [{"k": "list", "items": [[0, "False"], [0, "Rationale: The nurse first develops cultural self-awareness and then cultivates cultural sensitivity."]]}], "notes": "", "pics": 1}, {"n": 53, "title": "Thank you", "blocks": [], "notes": "", "pics": 1}]}, {"id": "M6", "en": "Vulnerable People: Chronic Diseases & Disabilities", "ar": "الفئات الهشة: الأمراض المزمنة والإعاقات", "scenarios": ["S6"], "slides": [{"n": 1, "title": "Working with Vulnerable People: Clients with Chronic Diseases or Disabilities  Chapter 23 & 24 2025-2026", "blocks": [], "notes": "", "pics": 1}, {"n": 2, "title": "Objectives", "blocks": [{"k": "list", "items": [[0, "Describe the term “vulnerable populations"], [0, "Discuss the Models and Theories of Vulnerability"], [0, "Describe the term “ Disability”"], [0, "Explain the socioeconomic gradient in health."], [0, "List the most common factors related to vulnerability"], [0, "Describe types of health disparities."], [0, "Identify strategies to solicit and evaluate input from vulnerable populations when planning health care programs and services."], [0, "Discuss the role of community/ public health nurse with vulnerable population."]]}], "notes": "", "pics": 0}, {"n": 3, "title": "Vulnerability", "blocks": [{"k": "list", "items": [[0, "The concept of vulnerability is an important one for nurses because of its implications for health, no matter where they practice. Is being susceptible to neglect or harm or being at risk of poor social, psychological, and physical Health out come (Aday2001)."]]}], "notes": "", "pics": 1}, {"n": 4, "title": "Vulnerable Populations", "blocks": [{"k": "list", "items": [[0, "Subpopulations such as ethnic or racial minorities, the uninsured, those with HIV/AIDS, children, the elderly the poor and those who are homeless (Shi & Stevens, 2011)."]]}], "notes": "", "pics": 0}, {"n": 5, "title": "Models and Theories of Vulnerability", "blocks": [{"k": "list", "items": [[0, "1- Vulnerable Populations Conceptual Model – Flaskerud & Winslow (1998)"], [0, "2- Behavioral Model for Vulnerable Populations – Gelberg, Andersen, & Leake (2000)"], [0, "3- Differential Vulnerability Hypothesis – Kessler (1979)"], [0, "4- Social Capital"]]}], "notes": "", "pics": 0}, {"n": 6, "title": "Models and Theories of Vulnerability", "blocks": [{"k": "list", "items": [[0, "1- Vulnerable Populations Conceptual Model – Flaskerud & Winslow (1998)"], [0, "Flaskerud & Winslow (1998) developed a popular conceptual framework of vulnerability that contains three related concepts:"], [0, "Resource Availability, Relative Risk, and Health Status."], [0, "The model provides evidence of the link between poor health status and socioeconomic resource availability through the loss of income, jobs, and health insurance"]]}], "notes": "", "pics": 0}, {"n": 7, "title": "1- Vulnerable Populations Conceptual Model – Flaskerud & Winslow (1998)", "blocks": [{"k": "list", "items": [[0, "Lack of resources (e.g., socioeconomic and environmental) increases a population's exposure to risk factors and reduces individuals' ability to avoid illness"], [0, "Socioeconomic resources include human capital (e.g., jobs, income, housing, education), social connectedness or integration (e.g., social networks or ties; social support or the lack of it, characterized by marginalization), and social status (e.g., position, power, role)"], [0, "Environmental resources deal mostly with access to health care and the quality of that care."], [0, "Relative risk refers to exposure to risk factors identified by a substantial body of research as lifestyle, behaviours and choices (e.g., diet, exercise, use of tobacco, alcohol and other drugs, sexual behaviours), use of health screening services (e.g., mammogram, colonoscopy), and stressful events (e.g., crime, violence, abuse, firearm use)."], [0, "Health Status:"], [0, "This is the result — it shows how healthy or unhealthy the person is. Poor resources and higher risk usually lead to poor health status."]]}], "notes": "", "pics": 0}, {"n": 8, "title": "1- Vulnerable Populations Conceptual Model – Flaskerud & Winslow (1998)", "blocks": [{"k": "list", "items": [[0, "A community’s health status can be observed by noting disease prevalence along with morbidity & mortality rates."], [0, "The central point of the model demonstrates the importance of nursing research & practice, along with ethical & policy analysis, in affecting resources, relative risk, & health status"]]}], "notes": "", "pics": 1}, {"n": 9, "title": "2- Behavioral Model for Vulnerable Populations – Gelberg, Andersen, & Leake (2000)", "blocks": [{"k": "list", "items": [[0, "This model looks at population characteristics (predisposing and enabling factors and needs) as an explanation for health behaviors and eventual health outcomes (Burg & Oyama, 2016). The following concepts are supported by this model:"], [0, "Predisposing factors included demographic variables (e.g., gender, age, marital status), social variables (e.g., education, employment, ethnicity, social networks), and health beliefs (e.g., values and attitudes toward health and health care services, knowledge of disease)."], [0, "Enabling factors: Personal/family resources and community resources (income, insurance, social support, region, health services, transportation)."]]}], "notes": "", "pics": 0}, {"n": 10, "title": "2- Behavioral Model for Vulnerable Populations – Gelberg, Andersen, & Leake (2000)", "blocks": [{"k": "list", "items": [[0, "Need factors: Perceived health needs, population health conditions, health behaviors (diet, exercise, tobacco use, self-care, adherence)."], [0, "The use of health services (e.g., ambulatory and inpatient care, long-term care, alternative health care) and personal health practices (e.g., hygiene, unsafe sexual behaviors, food sources) combined with the other factors to produce outcomes such as perceived and evaluated health and general satisfaction with health care service."], [0, "The model has been used in research with homeless adults (Doran et al., 2014)."]]}], "notes": "", "pics": 0}, {"n": 11, "title": "3. Differential Vulnerability Hypothesis – Kessler (1979)", "blocks": [{"k": "list", "items": [[0, "Kessler’s differential vulnerability hypothesis states that there is a relationship between social status and psychological distress; a person’s psychological distress is determined by the impact of the stressor event as influenced by social status (this includes class, sex, marital status, and rural vs. urban)."]]}], "notes": "", "pics": 0}, {"n": 12, "title": "3. Differential Vulnerability Hypothesis – Kessler (1979)", "blocks": [{"k": "list", "items": [[0, "Psychological distress is the result of varying exposure to environmental stress events or situations (S) acting on individuals who possess varying vulnerabilities to stress (V); (a) represents the residual influence of constitutional makeup of the mental health of person (i) independent of any environmental stresses he/she might experience”. The hypothesis has been used in research with racial inequity (Roxburgh & MacArthur, 2014; Wickrama, Bae & Walker, 2016)."], [0, "Stress–vulnerability model of psychological distress"], [0, "Psychological distress = S (stress) × [V (vulnerability) + a (constitutional makeup)]"]]}], "notes": "", "pics": 0}, {"n": 13, "title": "4- Social Capital", "blocks": [{"k": "list", "items": [[0, "The importance of social connections, support, and trust."], [0, "Having friends, family, or a close confidante can buffer stress and improve psychological and social health."], [0, "Social isolation increases risk for morbidity, mortality, and poor health outcomes."], [0, "Nurses should be aware of patients’ social capital and provide extra support if needed."]]}], "notes": "", "pics": 0}, {"n": 14, "title": "Socioeconomic Gradient of Health", "blocks": [{"k": "list", "items": [[0, "The direct relationship between social class or income and health has been termed the socioeconomic gradient (Hajizadeh, Mitnitski, & Rockwood, 2016). It has been found in populations around the world, although not always unfailingly, and has been related to Poor health outcomes regarding cardiovascular disease in European countries (Lenhart, Wiemken, Hanlon, Perkett, & Patterson, 2017). Cancer incidence, mortality, and survival in Western countries (Olver & Roder, 2017)."]]}], "notes": "", "pics": 0}, {"n": 15, "title": "Injury rates, such as blunt and penetrating injuries (Chikani et al., 2015) Increased burden of chro", "blocks": [{"k": "list", "items": [[0, "Outcomes of adult asthma, chronic obstructive pulmonary disease, and rhinitis (Torres-Duque, 2017) Behaviors, such as smoking, that are highest among those who are fromthe working class and who have low-income and low educational levels(Psaltopoulou et al., 2017)"]]}], "notes": "", "pics": 0}, {"n": 16, "title": "Who is considered vulnerable?", "blocks": [], "notes": "", "pics": 0}, {"n": 17, "title": "Who is considered vulnerable?", "blocks": [{"k": "list", "items": [[0, "Factors and vulnerable population"]]}], "notes": "", "pics": 0}, {"n": 18, "title": "Disability", "blocks": [], "notes": "", "pics": 0}, {"n": 19, "title": "Do you know someone living with a disability?", "blocks": [{"k": "list", "items": [[0, "Have you cared for a patient living with a disability?"], [0, "What have you learned about their lives?"], [0, "What does the word disability mean to you?"]]}], "notes": "", "pics": 0}, {"n": 20, "title": "Disability", "blocks": [{"k": "list", "items": [[0, "Disability refers to the negative aspects of the interaction between individuals with a health condition (such as cerebral palsy and depression) and personal and environmental factors (such as negative attitudes, inaccessible transportation and public buildings, and limited social supports)” (WHO, 2011)"]]}], "notes": "", "pics": 1}, {"n": 21, "title": "Disability is the incapacity to do something because of a handicap- Physical, mental etc.", "blocks": [{"k": "list", "items": [[0, "Disability is linked to inability, which is defined as “the lack of ability to do something, whatever the reason, but usually through incompetence, weakness, lack of training”."], [0, "Disability is part of human life, and an impairment or condition does not define individuals, their health, or their talents and abilities."]]}], "notes": "", "pics": 1}, {"n": 22, "title": "", "blocks": [], "notes": "", "pics": 1}, {"n": 23, "title": "Causes of Disabilities", "blocks": [{"k": "list", "items": [[0, "Congenital:"], [0, "Genetic/hereditary factors"], [0, "Non-hereditary"], [0, "Acquired:"], [0, "Infectious"], [0, "Non-infectious (chronic diseases, malnutrition, addiction, age related)"], [0, "Accidents"]]}], "notes": "", "pics": 0}, {"n": 24, "title": "Types of Disabilities", "blocks": [{"k": "list", "items": [[0, "Mobility/ Locomotor"], [0, "Intellectual"], [0, "Developmental"], [0, "Cognitive/Mental"], [0, "Hearing"], [0, "Visual"], [0, "Speech"]]}], "notes": "", "pics": 1}, {"n": 25, "title": "Chronic diseases", "blocks": [], "notes": "", "pics": 0}, {"n": 26, "title": "Key characteristics of chronic diseases", "blocks": [], "notes": "", "pics": 0}, {"n": 27, "title": "The International Classification of Functioning, Disability, and Health (ICF)", "blocks": [{"k": "list", "items": [[0, "The International Classification of Functioning, Disability, and Health (ICF) is a framework and classification system developed by the World Health Organization (WHO) in 2001."], [0, "It provides a standardized and internationally accepted way of describing and organizing information about health, disability, and health-related domains."]]}], "notes": "", "pics": 1}, {"n": 28, "title": "The key aims of the ICF are the following:", "blocks": [{"k": "list", "items": [[0, "Provide a scientific basis for understanding and studying health and health-related states, outcomes, and determinations."], [0, "Establish a common language for describing health and health-related states to improve communication between different users."], [0, "Permit comparison of data across countries, health care disciplines, services, and time."], [0, "Provide a systematic coding scheme for health information systems."]]}], "notes": "", "pics": 1}, {"n": 29, "title": "International Classification of Functioning, Disability, and Health", "blocks": [{"k": "list", "items": [[0, "Is a universal classification system using standardized language"], [0, "that views the domains of health from a holistic viewpoint."], [0, "(approach for assessing people with disabilities)."]]}, {"k": "list", "items": [[0, "The following concepts:"], [0, "Body functions: physiologic functions of body"], [0, "Body structure: anatomic parts of the body"], [0, "Impairments: problems in body function or structure"], [0, "Activity: task or action"], [0, "Participation: to be involved in a life situation"], [0, "Activity limitations: difficulty an individual may have with an activity"], [0, "Participation restrictions: limitations in involvement"], [0, "Environmental factors: the physical and social environments where people live and conduct their lives"]]}], "notes": "", "pics": 0}, {"n": 30, "title": "", "blocks": [], "notes": "", "pics": 1}, {"n": 31, "title": "", "blocks": [], "notes": "", "pics": 1}, {"n": 32, "title": "Definition:", "blocks": [{"k": "list", "items": [[0, "Persons with disabilities include those who have long-term physical, mental, intellectual or sensory impairments which in interaction with various barriers may hinder their full and effective participation in society on an equal basis with others"], [0, "Purpose of the convention:"], [0, "To promote, protect and ensure the full and equal enjoyment of all human rights and fundamental freedoms by all persons with disabilities, and to promote respect for their inherent dignity."]]}], "notes": "", "pics": 1}, {"n": 33, "title": "The United Nations Convention on the Rights of Persons with Disabilities", "blocks": [], "notes": "", "pics": 0}, {"n": 34, "title": "Health Promotion and Prevention Needs of the Disabled and Chronically ill", "blocks": [{"k": "list", "items": [[0, "Misconceptions Impeding Improvement:"], [0, "All people with disabilities have poor health."], [0, "Public health activities need to focus only on preventing disability."], [0, "There is no need for a clear definition of “disability” or “people with disabilities” in public health practice."], [0, "Environment does not play a significant role in the disability process."]]}], "notes": "", "pics": 0}, {"n": 35, "title": "Missed Opportunities", "blocks": [{"k": "list", "items": [[0, "Focus of health care delivery system: increasingly skewed toward secondary and tertiary prevention; limited emphasis on health promotion"], [0, "Areas of secondary and tertiary prevention that may be unique to persons with disabilities or chronic illnesses that are completely ignored"], [0, "Disability or illness usually as the initial reason for care; often drives selection of prevention efforts to the possible exclusion of other equally important issues"], [0, "Health care disparities and discrimination"]]}], "notes": "", "pics": 0}, {"n": 36, "title": "MISSED OPPORTUNITIES EXAMPLE", "blocks": [{"k": "list", "items": [[0, "A 60-year-old woman, blind since birth, self-sufficient, and active all of her life, has developed severe arthritis. She encounters a health care system that far too often focuses on her “disabilities” and not her “abilities” .The focus is placed squarely on her tertiary health promotion needs, often at the expense of health-promoting or lifestyle-enhancing needs. The result is a failure to recognize that the “disability” of arthritis is likely no less and no more an issue for her than for a sighted person. She receives the same medication therapy as does a sighted person but may not be offered a physical therapy program because of her disability. Her need for physical therapy is no less important, but locating an appropriate, safe, and easily accessible program requires some additional work on the part of her provider. The issue is that options potentially discussed with a sighted person are more apt to be omitted completely, which may negatively affect the client’s overall health and well-being."]]}], "notes": "", "pics": 0}, {"n": 37, "title": "Health Care Disparities and Discrimination", "blocks": [{"k": "list", "items": [[0, "When an individual receives unequal, inappropriate, or limited services compared with those received by others, this is categorized as discrimination."], [0, "The incidence of unequal and inappropriate practices can be reduced with education and training of health care providers, agency staff, and insurance carriers."]]}], "notes": "", "pics": 1}, {"n": 38, "title": "Families with a Disabled or Chronically Ill Member", "blocks": [{"k": "list", "items": [[0, "Family’s role in advocacy"], [0, "families face many challenges like"], [0, "They navigate a health care system that they may know little about ."], [0, "They serve as advocates for their (child, spouse, or parent) and may become exhausted or frustrated with their efforts."], [0, "Many demand assistance from health care agencies, social services, or transportation sources/ or open their home to others (e.g., community/public health nurses, social workers) ."], [0, "Families may also have little understanding of what services they are entitled to because of language barriers, difficult agency policies, or disjointed service delivery."]]}], "notes": "", "pics": 1}, {"n": 39, "title": "The PHN must earn the trust and confidence of the family by:", "blocks": [{"k": "list", "items": [[0, "Practicing consistency"], [0, "Following through with promised actions,"], [0, "Always being truthful."]]}], "notes": "", "pics": 1}, {"n": 40, "title": "The impact of caregiving on families", "blocks": [{"k": "list", "items": [[0, "The Impact on the family:"], [0, "High level of anxiety, stress, depression, social isolation,  illness and financial burden."], [0, "Obstacles, such as assistive devices and technology and financing, respite care, entitlements, loss of work, caregiver health, and mental health status."], [0, "The PHN is in an optimal position to:"], [0, "Interpret health care systems to the families and to advocate for the needed care, services, and equipment."], [0, "View the family holistically,"], [0, "Recognize additional needs that may develop as a result of the situation currently faced."], [0, "Include an assessment of caregiver and family work patterns when caring for families with a disabled or chronically ill family member."]]}], "notes": "", "pics": 1}, {"n": 41, "title": "UNIVERSAL DESIGN", "blocks": [{"k": "list", "items": [[0, "Is the concept of purposely creating environments in a way that they are accessible to all without the need for modifications"]]}, {"k": "list", "items": [[0, "Handicap access shower"]]}, {"k": "list", "items": [[0, "Ramps are needed for those using wheelchairs"], [0, "to gain access to buildings."]]}], "notes": "", "pics": 2}, {"n": 42, "title": "THE ROLE OF THE COMMUNITY/PUBLIC HEALTH NURSE", "blocks": [{"k": "list", "items": [[0, "Advocate for health care needs for disabled and chronically ill need for broad and holistic practice."], [0, "Creativity, tenacity, honesty, and knowledge to make needed changes at the individual, family and community level to improve their lives."], [0, "Involvement in wide-ranging, multiple roles, collaborate with other professionals and at different levels"], [0, "Community based intervention that help support disabled population with self management skills, improve health behaviors, and prevent secondary disabilities."]]}], "notes": "", "pics": 1}, {"n": 43, "title": "Services Available in Kingdom of Bahrain", "blocks": [{"k": "list", "items": [[0, "Ministry of Health"], [0, "Ministry of Social Development"], [0, "Ministry of Education"], [0, "The Private Sector"], [0, "NGO’s"], [0, "The Supreme Council for Youth and Sports"], [0, "Other Services"]]}], "notes": "", "pics": 3}, {"n": 44, "title": "Ministry of Health", "blocks": [], "notes": "", "pics": 0}, {"n": 45, "title": "Ministry of Health", "blocks": [{"k": "list", "items": [[0, "Rehabilitative centers provide remedial, rehabilitative, occupational, educational and entertainment services."], [0, "The centers are:"], [0, "NBB Rehabilitation Home For Disabled Children (moderate-severe mental retardation, >12 years)"], [0, "Academic and vocational rehabilitation center(mild –moderate mental retardation,12-15, >15)"], [0, "BBK rehabilitation center (moderate or severe mental, physical, >16)"], [0, "Shaikhan Alfarsi Center for Total Communication (auditory, 2.5-8years)"], [0, "Children day care center (multiple disabilities, 3-12years)"]]}], "notes": "", "pics": 1}, {"n": 46, "title": "Ministry of Health", "blocks": [], "notes": "", "pics": 0}, {"n": 47, "title": "Ministry of Education", "blocks": [{"k": "list", "items": [[0, "The Bahraini constitution states that education is available free of charge for all citizens."], [0, "The special education directorate in the ministry determines the cases that can join the governmental schools and supervises all disabled students including those studying abroad."], [0, "Integration of persons with disability in the schools: complete Remedial classes for slow learners are available in some schools (physical, visual), partial (down’s, mild MR, learning disabilities)."], [0, "Modifying the school environment to suit the disabled."], [0, "Training of the staff ."]]}], "notes": "", "pics": 1}, {"n": 48, "title": "Private Sector", "blocks": [{"k": "list", "items": [[0, "Works closely with Ministry of Social development."], [0, "These centers include:"], [1, "Bahrain comprehensive center for caring and rehabilitating persons with special needs."], [1, "The Bahraini institution for special education."], [1, "Autism center."], [1, "Partnership with the ministry of social development:"], [1, "Al-Matrook center"], [1, "The mobile unit project"]]}], "notes": "", "pics": 2}, {"n": 49, "title": "NGO’ s related to Disability:", "blocks": [], "notes": "", "pics": 1}, {"n": 50, "title": "NGO’ s related to Disability", "blocks": [{"k": "list", "items": [[0, "Center for Bahrain Mobility International"], [0, "Friendship Association for the Blind"], [0, "The Bahraini union for disabled sports"], [0, "National Foundation for Disabled Services"], [0, "Bahrain association for mental retardation"], [0, "Saudi Bahraini institute for the blind"], [0, "Bahrain association for Down’s syndrome"], [0, "Bahrain Society for the parents and friends of the disabled."], [0, "Bahrain Society for Children with difficulty in communication and behavior"], [0, "Society of Friends of cerebral palsy"], [0, "Cochlear Implant Association"], [0, "Bahrain association of hearing, speech and vision impairment"], [0, "Deaf club"], [0, "Bahrain deaf association"]]}], "notes": "", "pics": 0}, {"n": 51, "title": "NGO’ s related to Disability:", "blocks": [{"k": "list", "items": [[0, "Bahrain Mobility International (BMI) kindergarten"], [0, "BMI Nursery"], [0, "Al-Wafa Center(MR)"], [0, "Al-Wafa Center (Autism)"], [0, "Saudi Bahraini Institute for the Blind"], [0, "Al-Rahma Center"], [0, "Al-Hidd Center for Rehabilitating the Special Needs Persons"], [0, "Friendship for the Blind Kindergarten"], [0, "Al-Rashad Center"], [0, "Hope Institute for Early Care"], [0, "Prince Sultan Bin Abdul-Aziz Center for Development of Hearing and Speech"], [0, "Down’s Syndrome Center"], [0, "Alia Center for Early Intervention"]]}], "notes": "", "pics": 1}, {"n": 52, "title": "The supreme council for youth and sports", "blocks": [], "notes": "", "pics": 1}, {"n": 53, "title": "Other Services", "blocks": [], "notes": "", "pics": 0}, {"n": 54, "title": "Thank You", "blocks": [], "notes": "", "pics": 0}]}, {"id": "M7", "en": "School Nursing", "ar": "التمريض المدرسي", "scenarios": ["S7"], "slides": [{"n": 1, "title": "School Nursing", "blocks": [{"k": "list", "items": [[0, "College of Health & Sport Sciences"], [0, "Department of Nursing"], [0, "NUR 415 (2025-26) – 1st SEM"], [0, "BSc. Nursing"]]}], "notes": "", "pics": 2}, {"n": 2, "title": "Objectives", "blocks": [{"k": "list", "items": [[0, "By the end of this session, students will be able to:"], [0, "Define school health nursing and explain its purpose within the educational and healthcare systems."], [0, "Describe the historical development of school nursing, including contributions by Lillian Wald and Lina Rogers."], [0, "Identify the core roles and responsibilities of the school nurse as outlined by the American Academy of Pediatrics (AAP, 2016) and the National Association of School Nurses (NASN, 2019)."], [0, "Explain the key components of the Framework for 21st Century School Nursing Practice and its focus on student-centered, community-based care."], [0, "Demonstrate how school nurses manage chronic health conditions (e.g., asthma, diabetes, epilepsy, allergies) through individualized health plans (IHPs) and emergency action plans."]]}], "notes": "", "pics": 0}, {"n": 3, "title": "Introduction", "blocks": [{"k": "list", "items": [[0, "Many nursing students are unaware of the diverse career opportunities beyond hospital walls."], [0, "Community-based nursing roles—such as public health nursing (C/PHN), school nursing, and correctional nursing—are vital parts of publicly funded health systems."], [0, "Remember:"], [0, "Community nurses share several key characteristics:"], [0, "Apply the nursing process to populations or groups rather than individuals."], [0, "Focus on prevention of disease and disability."], [0, "Work with vulnerable populations."], [0, "Emphasize population-based care, collaboration, and networking with agencies and professionals (e.g., mental health workers, correctional officers)."], [0, "Act as advocates for individuals and communities."], [0, "Must be autonomous, flexible, creative thinkers, and self-directed in planning and delivering evidence-based care."]]}], "notes": "", "pics": 0}, {"n": 4, "title": "Public Health Nursing", "blocks": [{"k": "list", "items": [[0, "Community Settings for Public Health Nursing"], [0, "C/PHNs can work in diverse settings, such as:"], [0, "Schools, public health departments, and local government agencies"], [0, "Environmental health advocacy (e.g., transportation, safety policies)"], [0, "Global health initiatives (due to globalization and travel)"], [0, "Home visits and family health education"], [0, "Geriatric care (home care, assisted living, long-term facilities)"], [0, "Correctional facilities, promoting healthy lifestyles and disease management during incarceration"]]}], "notes": "", "pics": 0}, {"n": 5, "title": "Public Health Nursing", "blocks": [{"k": "list", "items": [[0, "Key Functions of the Public Health Nurse"], [0, "C/PHNs can work in diverse settings, such as:"], [0, "Focus on the health of populations rather than individuals."], [0, "Reflect the needs and priorities of communities."], [0, "Build caring and culturally sensitive relationships."], [0, "Are grounded in social justice, compassion, and equity."], [0, "Integrate understanding of physical, emotional, social, mental, spiritual, and environmental health."], [0, "Base their interventions on epidemiologic evidence."], [0, "Use collaborative strategies to achieve results."]]}], "notes": "", "pics": 0}, {"n": 6, "title": "School Nursing", "blocks": [], "notes": "", "pics": 1}, {"n": 7, "title": "School Nursing", "blocks": [{"k": "list", "items": [[0, "School Nursing is a specialized practice that supports student well-being, academic success, and lifelong achievement."], [0, "School nurses act as a link between school, family, community, and the healthcare system."], [0, "School nurses are ethical, evidence-based leaders who bridge health and education, coordinate care, and advocate for student-centered systems that promote individual and community potential."], [0, "Historical Background"], [0, "1902: Lillian Wald’s Henry Street Settlement pioneered school nursing in New York."], [0, "Lina Rogers was the first school nurse, conducting home visits to help sick children return to school."], [0, "Early school nurses advocated for:"], [1, "Hot lunch and breakfast programs"], [1, "Better hygiene and health education"], [1, "Improved social conditions for families"]]}], "notes": "", "pics": 0}, {"n": 8, "title": "School Nursing", "blocks": [], "notes": "", "pics": 2}, {"n": 9, "title": "School Nursing", "blocks": [{"k": "list", "items": [[0, "Framework for 21st century school nursing practice; National Association for School Nurses. (NASN, 2019)."], [0, "Students – Healthy, Safe, and Ready to Learn."], [0, "The framework emphasizes a student-centered and family/community-focused approach."]]}, {"k": "table", "rows": [["Domain", "Key Concepts", "Examples of School Nurse Roles/Activities"], ["1. Care Coordination", "Case management, chronic disease management, interdisciplinary teams", "Collaborating with teachers and families to support students with asthma, diabetes, ADHD, etc."], ["2. Leadership", "Advocacy, policy development, ethical practice, professional development", "Leading health initiatives, influencing school health policies"], ["3. Quality Improvement", "Data collection, evaluation, evidence-based practice, documentation", "Using student health data to improve care outcomes"], ["4. Community/Public Health", "Population-based care, screening, health education, emergency preparedness", "Conducting vaccination drives, promoting mental health awareness"], ["5. Standards of Practice", "Clinical competence, ethical practice, legal compliance", "Adhering to national nursing standards and scope of practice"]]}], "notes": "", "pics": 0}, {"n": 10, "title": "School Nursing", "blocks": [{"k": "list", "items": [[0, "School Nurse Core Responsibilities (AAP, 2016):"], [0, "Health Promotion: Promote the health and well-being of students, families, and school staff."], [0, "Case Management: a) Manage chronic conditions such as asthma, diabetes, epilepsy, and severe allergies. b) Develop individual health plans (IHPs) and emergency action plans."], [0, "Immunization Monitoring: Ensure all students are up to date with vaccinations and assist in accessing immunization services."], [0, "Special Education Support: Collaborate with teachers, parents, and psychologists to design and implement Individualized Education Plans (IEPs) for students with special needs."], [0, "Healthy School Environment: Work with school staff to ensure Safe playgrounds, Proper nutrition and hygiene, Physical activity programs, and Emergency preparedness."]]}], "notes": "", "pics": 0}, {"n": 11, "title": "School Nursing", "blocks": [{"k": "list", "items": [[0, "School Nurse Core Responsibilities:"], [0, "Community Collaboration"], [1, "Partner with public health departments, physicians, dentists, social services, and parent associations to meet students’ and families’ needs."], [0, "Screening and Health Education"], [1, "Conduct regular screenings (vision, hearing, growth, BMI, dental, mental health)."], [1, "Promote health and wellness programs for students and staff."], [0, "Direct Health Care"], [1, "Work with school-based health clinics to provide direct care to children and families."], [1, "Facilitates normal development and promotes positive outcomes through early interventions."], [0, "Coordinated School Health Programs"], [1, "Lead and support comprehensive programs combining health education, nutrition, counseling, and family/community involvement."]]}], "notes": "", "pics": 0}, {"n": 12, "title": "School Nursing", "blocks": [{"k": "list", "items": [[0, "The Whole School, Whole Community, Whole Child (WSCC) Model"], [0, "Developed by the Centers for Disease Control and Prevention (CDC, 2016)"], [0, "The WSCC model emphasizes that the child’s health, learning, and development are inseparable — and that the school and community must work together to support every child."]]}], "notes": "", "pics": 1}, {"n": 13, "title": "School Nursing", "blocks": [{"k": "list", "items": [[0, "The WSCC framework includes 10 key components that integrate health and education:"]]}, {"k": "table", "rows": [["Component", "Focus"], ["1. Health Education", "Teaching students healthy behaviors and prevention strategies."], ["2. Physical Education & Physical Activity", "Promoting movement, exercise, and fitness."], ["3. Nutrition Environment & Services", "Providing healthy meals and nutrition education."], ["4. Health Services", "Delivering screenings, immunizations, and emergency care."], ["5. Counseling, Psychological & Social Services", "Addressing emotional and behavioral needs."], ["6. Social & Emotional Climate", "Fostering a safe, respectful, and supportive atmosphere."], ["7. Physical Environment", "Maintaining clean, safe, and healthy school facilities."], ["8. Employee Wellness", "Supporting the health and well-being of school staff."], ["9. Family Engagement", "Involving families in student learning and health decisions."], ["10. Community Involvement", "Collaborating with community organizations and health agencies."]]}], "notes": "", "pics": 1}, {"n": 14, "title": "School Nursing", "blocks": [{"k": "list", "items": [[0, "The School Nurse’s Role within the WSCC Model"], [0, "The school nurse contributes to the WSCC model by:"], [0, "Acting as a liaison among school, family, and community health systems."], [0, "Promoting comprehensive health education and services."], [0, "Coordinating case management for students with chronic illnesses."], [0, "Advocating for safe and healthy school environments."], [0, "Supporting mental health and wellness initiatives."], [0, "Leading or co-leading coordinated school health programs."]]}], "notes": "", "pics": 1}, {"n": 15, "title": "School Nursing", "blocks": [{"k": "list", "items": [[0, "Major Chronic Conditions Managed by School Nurses"], [0, "1. Asthma"], [0, "The most common chronic disease in children, leading to over 13 million missed school days annually (Everhart et al., 2018)."], [0, "Symptoms: Wheezing, chest tightness, shortness of breath, and fatigue."], [0, "Environmental triggers: Mold, allergens, poor air quality, and dust."], [0, "School nurse roles:"], [1, "Develop and monitor Asthma Action Plans in collaboration with families and physicians."], [1, "Educate students on inhaler use and trigger avoidance."], [1, "Monitor medication adherence and emergency response protocols."], [1, "Train teachers and staff in asthma management and emergency procedures."]]}], "notes": "", "pics": 0}, {"n": 16, "title": "School Nursing", "blocks": [{"k": "list", "items": [[0, "Major Chronic Conditions Managed by School Nurses"], [0, "2. Diabetes"], [0, "About 208,000 children and adolescents live with diabetes in the U.S. (NASN, 2017)."], [0, "Types:"], [1, "Type 1: Autoimmune, requiring insulin therapy."], [1, "Type 2: Often associated with obesity and sedentary lifestyle."], [0, "School nurse responsibilities:"], [1, "Develop Diabetes Medical Management Plans (DMMPs)."], [1, "Provide care coordination, training, and delegation for diabetes care tasks."], [1, "Educate teachers and classmates to assist in emergencies."], [1, "Identify and respond to hypoglycemia or hyperglycemia immediately."], [1, "Promote healthy lifestyle habits to prevent Type 2 diabetes."]]}], "notes": "", "pics": 0}, {"n": 17, "title": "School Nursing", "blocks": [{"k": "list", "items": [[0, "Major Chronic Conditions Managed by School Nurses"], [0, "3. Seizure Disorders (Epilepsy)"], [0, "Caused by abnormal brain activity resulting in seizures."], [0, "Most cases controlled with medication, surgery, or specialized diets."], [0, "School nurse roles:"], [1, "Ensure medication compliance and proper documentation."], [1, "Train teachers and peers in first aid for seizures."], [1, "Promote empathy and reduce bullying or stigma."], [1, "Develop Emergency Seizure Action Plans and educate unlicensed assistive personnel (UAP) on safe medication administration (e.g., Diastat, midazolam)."]]}], "notes": "", "pics": 0}, {"n": 18, "title": "School Nursing", "blocks": [{"k": "list", "items": [[0, "Major Chronic Conditions Managed by School Nurses"], [0, "4. Food Allergies and Anaphylaxis"], [0, "Affect approximately 5.9 million school-aged children (FARE, 2018)."], [0, "Common triggers: Peanuts, tree nuts, shellfish, milk, eggs, soy, wheat, and fish."], [0, "School nurse duties:"], [1, "Develop Allergy and Anaphylaxis Emergency Plans."], [1, "Ensure availability of epinephrine auto-injectors (EpiPen)."], [1, "Train teachers, cafeteria staff, and bus drivers on emergency response."], [1, "Collaborate with families and school staff to minimize allergen exposure."]]}], "notes": "", "pics": 0}, {"n": 19, "title": "School Nursing", "blocks": [{"k": "list", "items": [[0, "Major Chronic Conditions Managed by School Nurses"], [0, "5. Behavioral and Learning Disorders"], [0, "Emotional, behavioral, and intellectual problems affect 10–15% of children worldwide (NIMH, 2018)."], [0, "Common conditions:"], [1, "ADHD, Oppositional Defiant Disorder, Bipolar Disorder, and early-onset Schizophrenia."], [0, "School nurse responsibilities:"], [1, "Early identification and referral to mental health services."], [1, "Advocate for counseling, behavioral therapy, and medication monitoring."], [1, "Work with teachers and families to develop supportive learning environments."], [1, "Educate staff and students on mental health awareness and empathy."]]}], "notes": "", "pics": 0}, {"n": 20, "title": "References", "blocks": [{"k": "list", "items": [[0, "Rector, C. L. (2018). Community Health Nursing:  Promotion & Protecting the Public’s Health. 9th ed. Philadelphia: Wolters Kluwer Lippincott Williams and Wilkins."], [0, "Robinson, M., Coehlo, D. P., & Smith, P. S. (2022). Family health care nursing : theory, practice, and research (7th edition). F.A. Davis Company."]]}], "notes": "", "pics": 0}, {"n": 21, "title": "Thank you", "blocks": [], "notes": "", "pics": 0}]}, {"id": "M8", "en": "Violence & Abuse", "ar": "العنف والإساءة", "scenarios": ["S8"], "slides": [{"n": 1, "title": "College of Health & Sport Sciences", "blocks": [{"k": "list", "items": [[0, "Department of Nursing"], [0, "NUR 415 (2025-26) – 1st SEM"], [0, "BSc. Nursing"]]}, {"k": "list", "items": [[0, "Violence &"], [0, "Abuse"]]}], "notes": "", "pics": 2}, {"n": 2, "title": "Objectives", "blocks": [{"k": "list", "items": [[0, "By the end of this session, students will be able to:"], [0, "Define key concepts related to violence and crisis, including WHO and CDC definitions."], [0, "Describe the types and forms of violence encountered across the lifespan (child abuse, intimate partner violence, elder abuse, etc.)."], [0, "Differentiate between risk factors and protective factors influencing violence at individual, relationship, community, and societal levels."], [0, "Recognize the signs and symptoms of physical, emotional, sexual, and neglect-related abuse in children and vulnerable populations."], [0, "Explain the cycle of violence in intimate partner relationships and its health implications."], [0, "Identify the nursing roles in the primary, secondary, and tertiary prevention of violence and crisis."]]}], "notes": "", "pics": 0}, {"n": 3, "title": "Introduction", "blocks": [{"k": "list", "items": [[0, "Violence is a global public health issue."], [0, "It is not limited by sociodemographic or geographic factors—anyone may experience violence or abuse at any point in one's lifetime."], [0, "Acts of violence may occur once or multiple times and involve a single perpetrator or a group of perpetrators who may or may not be known to the person experiencing violence."], [0, "Violence and abuse may occur in any setting—at home, in public, at work, or at school."]]}], "notes": "", "pics": 0}, {"n": 4, "title": "Definitions", "blocks": [{"k": "list", "items": [[0, "Violence:"], [0, "The World Health Organization defines violence as “the intentional use of physical force or power, threatened or actual, against oneself, another person, or a group or community, that either results in or has a high likelihood of resulting in injury, death, psychological harm, maldevelopment, or deprivation.”"], [0, "Crisis:"], [0, "Stressful/disruptive event(s) that disturb the equilibrium of an individual, family, or community. Can occur with or without warning"]]}], "notes": "", "pics": 1}, {"n": 5, "title": "Dynamics and characteristics of a crisis", "blocks": [{"k": "list", "items": [[0, "Each person is a dynamic system living within a given environment under the circumstances unique to that person alone."], [0, "Occurs when an internal or external force disrupts an individual’s balance, affecting functioning."], [0, "Individual attempts to restore equilibrium using available resources."], [0, "Inability to cope effectively = crisis (Boyd, 2018)."], [0, "Typically resolved within 4–8 weeks (Kanel, 2019)."], [0, "Long-term biopsychosocial effects may persist, especially after violence or trauma."]]}], "notes": "", "pics": 0}, {"n": 6, "title": "Types of Crisis", "blocks": [{"k": "table", "rows": [["Type", "Characteristics", "Examples"], ["Developmental Crisis", "Part of normal growth; gradual onset; related to life transitions and societal expectations", "Adolescence, marriage, retirement"], ["Situational Crisis", "Unexpected disruption in normalcy; event jeopardizes physical/psychological well-being; internal or external origin", "Illness (cancer), job loss"], ["Traumatic Crisis", "Sudden, overwhelming, unusual event; affects individual or group; causes death, injury, or destruction", "Natural disasters, acts of violence, terrorism"]]}], "notes": "", "pics": 0}, {"n": 7, "title": "Overview of violence across the life cycle", "blocks": [{"k": "list", "items": [[0, "Violence can occur from birth to death, in chronic or sudden forms:"], [0, "Chronic: Long-term abuse, neglect, or maltreatment"], [0, "Situational: Unexpected, acute events"], [0, "Types of violence encountered by C/PHNs:"], [0, "Child abuse and neglect"], [0, "Youth violence, bullying, gang violence"], [0, "Intimate partner violence (IPV) and dating violence"], [0, "Sexual violence"], [0, "Elder abuse and neglect"], [0, "Multiple types of violence can occur within a single household, community, or neighborhood, affecting people at different stages in life."]]}], "notes": "", "pics": 0}, {"n": 8, "title": "Overview of violence across the life cycle", "blocks": [{"k": "list", "items": [[0, "Different types of violence are interconnected. For example:"], [0, "People who experience one form of violence are likely to experience other forms of violence."], [0, "People who use violence in a context are likely to use it in another context."], [0, "Different types of violence share common short-and long-term biopsychosocial health effects that may contribute to chronic health conditions such as cardiovascular disease, lung disease, and diabetes."], [0, "Shared risk and protective factors exist across different types of violence."]]}], "notes": "", "pics": 0}, {"n": 9, "title": "Overview of violence across the life cycle", "blocks": [{"k": "list", "items": [[1, "Understanding trauma improves trauma-informed care"], [1, "Many victims are revictimized or misunderstood due to lack of knowledge about normal trauma responses"], [1, "Reactions to trauma are highly individual—no “one-size-fits-all” response"], [1, "Extraneous factors (substance use, past trauma, neurological patterns) influence responses"], [0, "Trauma-informed practices:"], [1, "Improve nurse interviews and anticipation of support they need for coping with the physiological and psychological impact of traumatic experience"], [1, "Enhance linkage to community resources"], [1, "Focus on physiological and psychological impacts"]]}], "notes": "", "pics": 0}, {"n": 10, "title": "Risk Factors and Protective Factors for Violence", "blocks": [{"k": "list", "items": [[0, "Risk factors: Increase likelihood of experiencing or using violence"], [0, "Protective factors: Reduce likelihood or enhance resilience after violence"], [0, "Individual experiences and characteristics can act as either"]]}], "notes": "", "pics": 0}, {"n": 11, "title": "Overview of violence across the life cycle", "blocks": [{"k": "list", "items": [[1, "Examples from CDC (2020c)"], [0, "Protective Factors:"], [0, "Community: Coordinated services and services among community agencies, mental health/substance abuse access, social connectedness"], [0, "Relationship: Family support, caring adult relationships, prosocial peer connections, school attachment"], [0, "Individual: Nonviolent problem-solving skills"]]}], "notes": "", "pics": 0}, {"n": 12, "title": "Overview of violence across the life cycle", "blocks": [{"k": "list", "items": [[1, "Examples from CDC (2020c)"], [0, "Risk Factors:"], [0, "Societal: Cultural norms supporting aggression, violent media, income inequity, harmful gender norms"], [0, "Community: Neighborhood poverty, high alcohol availability, community violence, unemployment, poor cohesion"], [0, "Relationship: Social isolation, poor parent–child relationships, family conflict, delinquent peer associations"], [0, "Individual: Low education, poor behavioral control, impulsivity, prior victimization, mental health/substance issues"]]}], "notes": "", "pics": 0}, {"n": 13, "title": "Overview of violence across the life cycle", "blocks": [{"k": "list", "items": [[0, "What are some of the risk factors and  protective factors in your community?"]]}], "notes": "", "pics": 0}, {"n": 14, "title": "Myths and Truths About Violence and Abuse", "blocks": [], "notes": "", "pics": 1}, {"n": 15, "title": "FAMILY VIOLENCE AGAINST CHILDREN", "blocks": [], "notes": "", "pics": 1}, {"n": 16, "title": "FAMILY VIOLENCE AGAINST CHILDREN", "blocks": [{"k": "list", "items": [[0, "Child abuse (CAPTA, 2019):Any act or failure to act by a parent/caregiver resulting in death, serious harm, sexual abuse, or an imminent risk of serious harm."], [0, "Child maltreatment (WHO, 2020):All forms of abuse and neglect toward children under 18 that result in actual or potential harm to health, development, or dignity within a relationship of responsibility, trust, or power."], [0, "Global Perspective"], [0, "25% of adults report physical abuse in childhood."], [0, "36% report emotional abuse; 16.3% report neglect."]]}], "notes": "", "pics": 0}, {"n": 17, "title": "Major Types of FAMILY VIOLENCE AGAINST CHILDREN", "blocks": [{"k": "list", "items": [[0, "Child Neglect"]]}, {"k": "list", "items": [[0, "Physical Abuse"]]}, {"k": "list", "items": [[0, "Sexual abuse"]]}, {"k": "list", "items": [[0, "Emotional/ Psychological abuse"]]}, {"k": "list", "items": [[0, "Specific Abusive Situations:"], [0, "1- Abusive Head Trauma (Shaken Baby Syndrome)"], [0, "2. Munchausen Syndrome by Proxy"], [0, "3. Parental Filicide (Child Murder by Parent)"], [0, "4- Internet and Technology-Facilitated Crimes"], [0, "5. Child Abduction"], [0, "6. Abuse by Babysitters or Caretakers"], [0, "7. School Violence"]]}], "notes": "", "pics": 0}, {"n": 18, "title": "FAMILY VIOLENCE AGAINST CHILDREN", "blocks": [{"k": "list", "items": [[0, "Major Types of Child Abuse         A- NEGLECT"], [0, "Failure to provide basic physical, emotional, medical, or educational needs."], [0, "Types:"], [0, "Physical neglect: Poor hygiene, lack of food or shelter."], [0, "Medical neglect: Not providing necessary health care."], [0, "Educational neglect: Frequent absence, not enrolled in school."], [0, "Emotional neglect: Lack of affection, excessive or inappropriate demands."]]}], "notes": "", "pics": 1}, {"n": 19, "title": "FAMILY VIOLENCE AGAINST CHILDREN", "blocks": [{"k": "list", "items": [[0, "Major Types of Child Abuse         A- NEGLECT"], [0, "Examples:"], [0, "Parents may refuse to buy eyeglasses for a child who needs them or to access dental care for severely decayed teeth (medical neglect)."], [0, "An 8-year-old may get to school only 3 days a week, possibly without breakfast and no lunch money or packed lunch (educational neglect)."], [0, "A family with three children may live in a sparsely furnished apartment with very little food available and only intermittent heat and multiple people coming and going in the residence, while the children may appear at school unwashed and without coats in winter weather (general neglect)."], [0, "Emotional neglect may be seen when demands placed on a child are excessive or inappropriate for his or her development, or the caretaker berates or verbally humiliates a child frequently and without reason."]]}], "notes": "", "pics": 1}, {"n": 20, "title": "FAMILY VIOLENCE AGAINST CHILDREN", "blocks": [{"k": "list", "items": [[0, "Major Types of Child Abuse         A- NEGLECT"], [0, "Signs and Symptoms:"], [0, "Poor hygiene, malnutrition, inappropriate clothing."], [0, "Lack of medical/dental care or immunizations."], [0, "Poor supervision, unsafe home environment."], [0, "Sleepy, hungry, failure to thrive."], [0, "Nursing Considerations (C/PHN Role):"], [0, "Assess causes (lack of knowledge, finances, or access)."], [0, "Link families to support: WIC (Women, Infants, and Children Program), health insurance, education programs."], [0, "Remember: Neglect often discovered during investigations of other abuse."]]}], "notes": "", "pics": 0}, {"n": 21, "title": "FAMILY VIOLENCE AGAINST CHILDREN", "blocks": [{"k": "list", "items": [[0, "Major Types of Child Abuse         A- NEGLECT"], [0, "Signs and Symptoms:"], [0, "Poor hygiene, malnutrition, inappropriate clothing."], [0, "Lack of medical/dental care or immunizations."], [0, "Poor supervision, unsafe home environment."], [0, "Sleepy, hungry, failure to thrive."], [0, "Nursing Considerations (C/PHN Role):"], [0, "Assess causes (lack of knowledge, finances, or access)."], [0, "Link families to support: WIC (Women, Infants, and Children Program), health insurance, education programs."], [0, "Remember: Neglect often discovered during investigations of other abuse."]]}], "notes": "", "pics": 0}, {"n": 22, "title": "FAMILY VIOLENCE AGAINST CHILDREN", "blocks": [{"k": "list", "items": [[0, "Major Types of Child Abuse         B- Physical Abuse"], [0, "Intentional harm to a child by another person that results in pain, physical injury, or death."], [0, "Common Injuries:"], [0, "Bruises, burns, fractures, bite marks, head trauma."], [0, "Injuries inconsistent with child’s developmental stage."], [0, "Delayed medical attention."]]}], "notes": "", "pics": 1}, {"n": 23, "title": "FAMILY VIOLENCE AGAINST CHILDREN", "blocks": [{"k": "list", "items": [[0, "Major Types of Child Abuse                 B- Physical Abuse"], [0, "Signs and Symptoms:"], [0, "Frequent emergency department visits"], [0, "Caregiver blames child for injuries"], [0, "Delay in seeking health/medical care or changes provider frequently"], [0, "Explanation changes, doesn't match the child's developmental ability, or contradicts injuries"]]}], "notes": "", "pics": 0}, {"n": 24, "title": "FAMILY VIOLENCE AGAINST CHILDREN", "blocks": [{"k": "list", "items": [[0, "Major Types of Child Abuse                 B- Physical Abuse"], [0, "Signs and Symptoms:"], [0, "Has unexplained injuries, explanation does not match the injury, or injuries are inconsistent with medical diagnosis. such as Injuries may include bruises, bite marks, abrasions, lacerations, head injuries, internal injuries, and fractures"], [0, "Bruising from defensive injuries to forearms"], [0, "Burns from cigarettes, ropes, or immersion into hot water or hot grid"], [0, "Traumatic alopecia with possible hematoma area and is tender to touch"], [0, "Trauma to ear"], [0, "Appears depressed, withdrawn, anxious, or aggressive"], [0, "Appears scared of parent and does not want to go home"]]}], "notes": "", "pics": 0}, {"n": 25, "title": "FAMILY VIOLENCE AGAINST CHILDREN", "blocks": [{"k": "list", "items": [[0, "Major Types of Child Abuse                 B- Physical Abuse"], [0, "Behavioral Indicators:"], [0, "Attempts to hide injuries; child wears excessive layers of clothing, especially in hot weather."], [0, "Frequently absent from school or misses physical education classes."], [0, "Fearful, clingy, anxious, withdrawn, hypervigilant, or aggressive."], [0, "The child is apprehensive when other children cry."], [0, "Wary of physical contact with adults."], [0, "Exhibits drastic behavioral changes in and out of parental/caretaker presence."], [0, "The child suffers from seizures or vomiting."], [0, "Exhibits depression, self-mutilation, suicide attempts, substance abuse, or sleeping and eating disorders."], [0, "Fearful of going home."]]}], "notes": "", "pics": 0}, {"n": 26, "title": "FAMILY VIOLENCE AGAINST CHILDREN", "blocks": [{"k": "list", "items": [[0, "Major Types of Child Abuse                 C- Sexual Abuse"], [0, "Sexual abuse of children includes acts of sexual assault or sexual exploitation of a minor and may consist of a single incident or many acts over a long period."], [0, "Rape, molestation, prostitution, and human trafficking of minors are included in the definition."], [0, "Care for children who have been sexually abused varies, as the duration of the molestation, the age, and symptoms of the child will influence their care measures. Parents may also need counseling and support following the investigation and proceedings involving their child's victimization."]]}], "notes": "", "pics": 0}, {"n": 27, "title": "FAMILY VIOLENCE AGAINST CHILDREN", "blocks": [{"k": "list", "items": [[0, "Major Types of Child Abuse                 C- Sexual Abuse"], [0, "Incest is sexual abuse among family members who are related by blood (e.g., parents, grandparents, older sibling)."], [0, "Intrafamilial sexual abuse refers to sexual activity involving family members who are not related by blood (e.g., stepparents, partner of a parent)."], [0, "Commercial Sexual Exploitation (CSEC): Use of a child for sexual purposes in exchange for money, food, shelter, or protection. Includes child trafficking, pornography, and early forced marriage."]]}], "notes": "", "pics": 0}, {"n": 28, "title": "FAMILY VIOLENCE AGAINST CHILDREN", "blocks": [{"k": "list", "items": [[0, "Major Types of Child Abuse                 C- Sexual Abuse"], [0, "Signs and Symptoms:"], [0, "Physical Signs"], [0, "Sexually transmitted infections."], [0, "Trauma to the perineal area including bleeding, bruising, or pain."], [0, "Blood may be seen on sheets or undergarments."], [0, "Discharge from genitals or anus."], [0, "Pain during bowel movements or urination."]]}], "notes": "", "pics": 0}, {"n": 29, "title": "FAMILY VIOLENCE AGAINST CHILDREN", "blocks": [{"k": "list", "items": [[0, "Major Types of Child Abuse                 C- Sexual Abuse"], [0, "Signs and Symptoms:"], [0, "Behavioral Signs"], [0, "Enuresis and/or fecal soiling in bed when behavior has been outgrown"], [0, "Inappropriate sexual behavior for age"], [0, "Not wanting to be left alone with certain people or fearful to leave parent or caregiver"], [0, "Refuses to remove clothing"], [0, "Has money, gifts, or toys unexpectedly"], [0, "Self-injury/suicide attempts"], [0, "Sexually promiscuity in teens"], [0, "Substance use"]]}], "notes": "", "pics": 0}, {"n": 30, "title": "FAMILY VIOLENCE AGAINST CHILDREN", "blocks": [{"k": "list", "items": [[0, "Major Types of Child Abuse                 C- Sexual Abuse"], [0, "Signs and Symptoms:"], [0, "Emotional Signs"], [0, "Nightmares or fear of being left alone at night"], [0, "Extreme worry or fear"], [0, "Sexually explicit language or explicit knowledge about sexual"], [0, "topics beyond age of child"], [0, "Mood changes"]]}], "notes": "", "pics": 0}, {"n": 31, "title": "FAMILY VIOLENCE AGAINST CHILDREN", "blocks": [{"k": "list", "items": [[0, "Major Types of Child Abuse    D- Emotional / Psychological Abuse"], [0, "Emotional abuse of children involves psychological mistreatment or neglect, which impairs a child's self-worth and sense of security and being loved."], [0, "Types of psychological abuse includes rejection, scorn, terrorism, isolation, exploitation, lack of emotional response, exposure to domestic violence, and verbal threats or void of loving comments."], [0, "Emotional abuse alone is rarely reported because it is another hidden form of abuse."], [0, "Indicators:"], [0, "Extremes in behavior (passive, aggressive, overly compliant)."], [0, "Depression, low self-esteem, developmental delays."], [0, "Inability to form emotional bonds."]]}], "notes": "", "pics": 0}, {"n": 32, "title": "FAMILY VIOLENCE AGAINST CHILDREN", "blocks": [{"k": "list", "items": [[0, "Major Types of Child Abuse    E- Specific Abusive Situations"], [0, "E1: Abusive Head Trauma (Shaken Baby Syndrome)"], [0, "Intentional abusive action of violently shaking an infant or toddler."], [0, "Occurs in infants <2 years; leading cause of death from physical abuse."], [0, "Symptoms: seizures, respiratory distress, retinal hemorrhage, brain injury."], [0, "Outcome: 80% of survivors suffer lifelong disabilities."], [0, "E2: Munchausen Syndrome by Proxy"], [0, "A diagnosis applied to parents and other caregivers who intentionally feign, exaggerate, and/or induce illness or injury in a child to get attention from health professionals and others."], [0, "Caregiver induces or fabricates illness in a child for attention."], [0, "Often perpetrated by the biological mother."], [0, "Clues: unexplained illnesses, symptoms only in caregiver’s presence."]]}], "notes": "", "pics": 2}, {"n": 33, "title": "FAMILY VIOLENCE AGAINST CHILDREN", "blocks": [{"k": "list", "items": [[0, "Major Types of Child Abuse    E- Specific Abusive Situations"], [0, "E3: Parental Filicide (Child Murder by Parent)"], [0, "Includes infanticide (under 1 year) and neonaticide (within 24 hours)."], [0, "Risk factors: teen mothers, depression, poverty, isolation, lack of support."], [0, "E4: Internet and Technology-Facilitated Crimes"], [0, "Online grooming, sextortion, child pornography, cyberbullying."], [0, "E5: Child Abduction"], [0, "Child abduction by family members or intimate partners, such as a divorced mother, father, boyfriend, or grandparents, is more common."]]}], "notes": "", "pics": 3}, {"n": 34, "title": "FAMILY VIOLENCE AGAINST CHILDREN", "blocks": [{"k": "list", "items": [[0, "Major Types of Child Abuse    E- Specific Abusive Situations"], [0, "E6: Abuse by Babysitters or Caretakers"], [0, "Parents should verify references, licenses, and monitor childcare environments."], [0, "Red flags: unexplained injuries, fear of caregiver, neglect signs."], [0, "E7: School Violence"], [0, "Includes bullying, physical assaults, and mass shootings."], [0, "Risk factors: rejection, bullying, poor parental supervision, delinquency, poverty."], [0, "Statistics:19% bullied at school; 15% bullied electronically.6.7% missed school due to feeling unsafe.3.8% carried weapons to school."]]}], "notes": "", "pics": 1}, {"n": 35, "title": "INTIMATE PARTNER VIOLENCE", "blocks": [], "notes": "", "pics": 1}, {"n": 36, "title": "INTIMATE PARTNER VIOLENCE", "blocks": [{"k": "list", "items": [[0, "Abuse or aggression that occurs within a close relationship — either current or former partners (CDC, 2019)."], [0, "Domestic violence is “a pattern of abusive behavior in any relationship that is used by one partner to gain or maintain power and control over another intimate partner”; it may be emotional, economic, physical, psychological, or sexual in nature."], [0, "IPV is a major cause of morbidity, mortality, and human rights violations globally."], [0, "Main Types of IPV:"], [0, "Physical violence – hitting, slapping, choking, beating, etc."], [0, "Sexual violence – forced or coerced sexual acts."], [0, "Stalking – repeated unwanted attention or harassment causing fear."], [0, "Psychological aggression – verbal or emotional abuse, humiliation, control, or threats."]]}], "notes": "", "pics": 0}, {"n": 37, "title": "INTIMATE PARTNER VIOLENCE", "blocks": [{"k": "list", "items": [[0, "Prevalence and Statistics (CDC, 2019; WHO, 2017)"], [0, "1 in 4 women and 1 in 10 men experience physical/sexual violence or stalking."], [0, "1 in 5 women and 1 in 7 men experience severe physical violence."], [0, "1 in 5 women and 1 in 12 men experience sexual violence."], [0, "16% of all homicides are committed by an intimate partner."], [0, "43 million women and 38 million men have experienced psychological aggression"], [0, "35% of women worldwide have experienced IPV or non-partner sexual violence."], [0, "30% of women have been physically abused by a partner."], [0, "38% of murdered women were killed by an intimate partner."], [0, "IPV is a major cause of morbidity, mortality, and human rights violations globally."]]}], "notes": "", "pics": 0}, {"n": 38, "title": "INTIMATE PARTNER VIOLENCE", "blocks": [{"k": "list", "items": [[0, "The Cycle of Violence"]]}], "notes": "", "pics": 1}, {"n": 39, "title": "INTIMATE PARTNER VIOLENCE", "blocks": [{"k": "list", "items": [[0, "The Cycle of Violence"]]}, {"k": "list", "items": [[0, "A. Tension-Building Phase"], [0, "Longest phase — may last for weeks."], [0, "The abuser becomes irritable, controlling, and verbally abusive."], [0, "The victim feels anxious, cautious (“walking on eggshells”), and tries to appease the abuser to prevent escalation."], [0, "Minor incidents of abuse may occur."], [0, "Emotional stress increases as tension grows."]]}], "notes": "", "pics": 0}, {"n": 40, "title": "INTIMATE PARTNER VIOLENCE", "blocks": [{"k": "list", "items": [[0, "The Cycle of Violence"]]}, {"k": "list", "items": [[0, "B. Acute Explosion Phase (Crisis Phase)"], [0, "Shortest phase — usually 1–2 days."], [0, "Most violent period as tension is released."], [0, "Abuse may be physical, sexual, emotional, or verbal."], [0, "Often triggered by an external event or the abuser’s emotional state."], [0, "The abuser blames the victim for the violence."], [0, "The victim may fight back, flee, or submit to calm the situation."]]}], "notes": "", "pics": 0}, {"n": 41, "title": "INTIMATE PARTNER VIOLENCE", "blocks": [{"k": "list", "items": [[0, "The Cycle of Violence"]]}, {"k": "list", "items": [[0, "C. Honeymoon Phase"], [0, "The abuser feels remorse or shame and may apologize or justify their behavior."], [0, "Promises to change (e.g., quit drinking, be more attentive)."], [0, "May display affection and generosity (gifts, flowers, romantic gestures)."], [0, "The victim forgives and hopes the abuse will stop."], [0, "Temporary calm and emotional closeness return—then tension starts again."]]}], "notes": "", "pics": 0}, {"n": 42, "title": "INTIMATE PARTNER VIOLENCE", "blocks": [{"k": "list", "items": [[0, "The Wheel of Violence"]]}, {"k": "list", "items": [[0, "Eight Components of the Wheel"], [0, "1- Using Coercion and Threats"], [0, "2- Using Intimidation"], [0, "3- Using Emotional Abuse"], [0, "4- Using Isolation"]]}, {"k": "list", "items": [[0, "5- Minimizing, Denying, and Blaming"], [0, "6- Using Children"], [0, "7- Using Male Privilege"], [0, "8- Using Economic Abuse"]]}], "notes": "", "pics": 1}, {"n": 43, "title": "INTIMATE PARTNER VIOLENCE", "blocks": [{"k": "list", "items": [[0, "Violence in Special Populations – Teens and Pregnant Women"]]}, {"k": "list", "items": [[0, "1. Teen Dating Violence: A pattern of physical, sexual, psychological, or stalking behaviors between teens in a current or former dating relationship."], [0, "Can occur in person or electronically (e.g., social media, texting; CDC, 2019)"], [0, "2. Stalking: A pattern of repeated, unwanted attention, harassment, or contact that causes fear in the victim."], [0, "Forms of Cyberstalking include Online harassment or threats, Unauthorized sharing of private photos or messages, Impersonation or social media abuse."], [0, "3. Violence During Pregnancy: Intimate partner violence (IPV) during pregnancy includes physical, sexual, or emotional abuse directed toward a pregnant woman."], [0, "Severe outcomes include Depression, anxiety, and low self-esteem, Preterm labor and low birth weight, Intrauterine growth retardation and neonatal complications."]]}], "notes": "", "pics": 0}, {"n": 44, "title": "Batterer Characteristics", "blocks": [{"k": "list", "items": [[0, "INTIMATE PARTNER VIOLENCE"]]}, {"k": "list", "items": [[0, "Batterer and Victim Characteristics"]]}, {"k": "list", "items": [[0, "Low income"], [0, "Low self-esteem"], [0, "Low academic achievement"], [0, "Heavy alcohol and drug use"], [0, "Depression"], [0, "Anger and hostility"], [0, "Personality disorders"], [0, "Prior history of being physically abusive"]]}, {"k": "list", "items": [[0, "Having few friends and being isolated from other people"], [0, "Unemployment"], [0, "Emotional dependence and insecurity"], [0, "Belief in strict gender roles (e.g., male dominance and aggression in relationships)"], [0, "Desire for power and control in relationships"], [0, "Being a victim of physical or psychological abuse"]]}], "notes": "", "pics": 0}, {"n": 45, "title": "Victim Characteristics", "blocks": [{"k": "list", "items": [[0, "INTIMATE PARTNER VIOLENCE"]]}, {"k": "list", "items": [[0, "Batterer and Victim Characteristics"]]}, {"k": "list", "items": [[0, "A prior history of IPV"], [0, "Being female"], [0, "Young age, especially if pregnant"], [0, "From low-income household"], [0, "Witnessing or experiencing violence as a child"], [0, "Lower education level"], [0, "Unemployment"]]}, {"k": "list", "items": [[0, "Single parent with children or separated/divorced/previously widowed"], [0, "Having a greater education level than their partner"], [0, "For women, being disabled"], [0, "For women, having a verbally abusive, jealous, or possessive partner"]]}], "notes": "", "pics": 0}, {"n": 46, "title": "Elder Abuse and Maltreatment of Older Adults", "blocks": [], "notes": "", "pics": 1}, {"n": 47, "title": "Elder Abuse and Maltreatment of Older Adults", "blocks": [{"k": "list", "items": [[0, "“An intentional act or failure to act by a caregiver or another person in a relationship involving an expectation of trust that causes or creates a risk of harm to an older adult.” (CDC, 2019)"], [0, "Types of Elder Abuse include Physical Abuse, Sexual Abuse, Emotional/Psychological Abuse, Neglect, Passive Neglect, Financial/Material Exploitation, and Confinement or Willful Deprivation"]]}], "notes": "", "pics": 0}, {"n": 48, "title": "Elder Abuse and Maltreatment of Older Adults", "blocks": [{"k": "list", "items": [[0, "Prevalence:"], [0, "1 in 10 adults over age 65 experience some form of abuse.(USDOJ, 2018a)"], [0, "1 in 6 adults over age 60 globally experience abuse.(WHO, 2020b)"], [0, "About two-thirds of victims are women."], [0, "Nearly half of victims have dementia."], [0, "Neglect is the most commonly reported form, followed by financial exploitation and emotional abuse."]]}], "notes": "", "pics": 0}, {"n": 49, "title": "LEVELS OF PREVENTION:", "blocks": [{"k": "list", "items": [[0, "CRISIS INTERVENTION AND FAMILY AND INTIMATE PARTNER (IP)"], [0, "VIOLENCE"]]}], "notes": "", "pics": 1}, {"n": 50, "title": "LEVELS OF PREVENTION", "blocks": [], "notes": "", "pics": 2}, {"n": 51, "title": "LEVELS OF PREVENTION", "blocks": [{"k": "list", "items": [[0, "A) Primary Prevention – Stop Violence Before It Starts"], [0, "Goal: Prevent violence from occurring."], [0, "Focus: Promote health, prevent crises, and strengthen individuals/families."], [0, "Nursing Role:"], [0, "Promote positive relationships, parenting, and communication skills."], [0, "Build self-esteem and empower families to reduce stressors (e.g., poverty)."], [0, "Conduct home visiting programs (e.g., Nurse Family Partnership) to support at-risk mothers and prevent child abuse."], [0, "Foster healthy neighborhoods and community empowerment for safety."]]}], "notes": "", "pics": 1}, {"n": 52, "title": "LEVELS OF PREVENTION", "blocks": [{"k": "list", "items": [[0, "B) Secondary Prevention – Early Detection & Rapid Response"], [0, "Goal: Minimize harm and prevent further violence."], [0, "Focus: Early diagnosis, prompt intervention, and crisis resolution."], [0, "Nursing Role:"], [0, "Build rapport and assess for lethality."], [0, "Apply crisis intervention process (James & Gilliland, 2017):"], [1, "Establish rapport, Assess problem and lethality, Identify major problems, Deal with feelings, Explore coping strategies, Develop action plan, Follow up and plan for future crises"], [0, "Report suspected abuse (child, elder, or vulnerable adult) — mandated by law."], [0, "Maintain confidentiality, validate experiences, and refer to community services."], [0, "Promote a culture of safety (QSEN standards)."]]}], "notes": "", "pics": 1}, {"n": 53, "title": "LEVELS OF PREVENTION", "blocks": [{"k": "list", "items": [[0, "C) Tertiary Prevention – Healing and Rehabilitation"], [0, "Goal: Restore health, prevent recurrence, and promote recovery."], [0, "Focus: Long-term rehabilitation and family growth after violence."], [0, "Nursing Role:"], [0, "Support victims, families, and even offenders as appropriate."], [0, "Provide counseling, rehabilitation, and social reintegration services."], [0, "Continue referrals started during secondary prevention."], [0, "Address family stress due to incarceration or separation."], [0, "Support children and caregivers in managing ongoing emotional or legal challenges."], [0, "Understand the complex dynamics of victim–perpetrator relationships."]]}], "notes": "", "pics": 1}, {"n": 54, "title": "References", "blocks": [{"k": "list", "items": [[0, "Rector, C. L. (2018). Community Health Nursing:  Promotion & Protecting the Public’s Health. 9th ed. Philadelphia: Wolters Kluwer Lippincott Williams and Wilkins."], [0, "Robinson, M., Coehlo, D. P., & Smith, P. S. (2022). Family health care nursing : theory, practice, and research (7th edition). F.A. Davis Company."]]}], "notes": "", "pics": 0}, {"n": 55, "title": "Thank you", "blocks": [], "notes": "", "pics": 0}]}];
